CREATE OR REPLACE FUNCTION public.account_commercial_state(_account_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  acc public.accounts%ROWTYPE;
  sub public.account_subscriptions%ROWTYPE;
  onboarded boolean;
BEGIN
  SELECT * INTO acc FROM public.accounts WHERE id = _account_id;
  IF NOT FOUND THEN RETURN 'cancelled'; END IF;
  IF acc.status <> 'active' OR acc.blocked_at IS NOT NULL THEN RETURN 'suspended'; END IF;
  SELECT * INTO sub FROM public.account_subscriptions WHERE account_id = _account_id;
  IF sub.id IS NOT NULL AND sub.status IN ('active','cancellation_requested') THEN RETURN 'active'; END IF;
  IF sub.id IS NOT NULL AND sub.status IN ('payment_pending','grace_period') THEN RETURN 'payment_pending'; END IF;
  IF EXISTS (SELECT 1 FROM public.access_grants g WHERE g.account_id = _account_id AND g.kind = 'legacy' AND g.revoked_at IS NULL) THEN RETURN 'legacy'; END IF;
  IF EXISTS (SELECT 1 FROM public.access_grants g WHERE g.account_id = _account_id AND g.kind = 'admin_trial' AND g.revoked_at IS NULL AND g.starts_at <= now() AND g.ends_at > now()) THEN RETURN 'admin_trial'; END IF;
  IF sub.id IS NOT NULL AND sub.status = 'restricted' THEN RETURN 'overdue'; END IF;
  IF sub.id IS NOT NULL AND sub.status = 'cancelled' THEN RETURN 'cancelled'; END IF;
  IF EXISTS (SELECT 1 FROM public.access_grants g WHERE g.account_id = _account_id AND g.kind = 'standard_trial' AND g.revoked_at IS NULL AND g.starts_at <= now() AND g.ends_at > now()) THEN RETURN 'trial'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.access_grants g WHERE g.account_id = _account_id) THEN
    SELECT bool_or(p.onboarding_completed) INTO onboarded FROM public.profiles p WHERE p.account_id = _account_id;
    IF NOT coalesce(onboarded, false) THEN RETURN 'pre_trial'; END IF;
  END IF;
  RETURN 'awaiting_contract';
END; $function$

CREATE OR REPLACE FUNCTION public.admin_change_account_status(_actor_user_id uuid, _account_id uuid, _status text, _reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role public.platform_admin_role;
  actor_account_status TEXT;
  actor_account_blocked_at TIMESTAMPTZ;
  target_account public.accounts%ROWTYPE;
  normalized_reason TEXT := nullif(btrim(_reason), '');
BEGIN
  SELECT pa.role, a.status, a.blocked_at
  INTO actor_role, actor_account_status, actor_account_blocked_at
  FROM public.platform_admins pa
  JOIN public.accounts a ON a.owner_user_id = pa.user_id
  WHERE pa.user_id = _actor_user_id AND pa.revoked_at IS NULL;

  IF actor_role IS NULL OR actor_role NOT IN ('super_admin', 'support_admin')
     OR actor_account_status <> 'active' OR actor_account_blocked_at IS NOT NULL THEN
    RAISE EXCEPTION 'Operação não autorizada.';
  END IF;
  IF _status NOT IN ('active', 'suspended') THEN RAISE EXCEPTION 'Situação inválida.'; END IF;
  IF _status = 'suspended' AND normalized_reason IS NULL THEN RAISE EXCEPTION 'Informe a justificativa.'; END IF;

  SELECT a.* INTO target_account FROM public.accounts a WHERE a.id = _account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
  IF _status = 'suspended' AND target_account.owner_user_id = _actor_user_id THEN
    RAISE EXCEPTION 'Você não pode desativar sua própria conta administrativa.';
  END IF;
  IF _status = 'suspended' AND EXISTS (
    SELECT 1 FROM public.platform_admins pa
    WHERE pa.user_id = target_account.owner_user_id
      AND pa.role = 'super_admin'
      AND pa.revoked_at IS NULL
  ) AND (SELECT count(*) FROM public.platform_admins WHERE role = 'super_admin' AND revoked_at IS NULL) <= 1 THEN
    RAISE EXCEPTION 'O último administrador master ativo não pode ser desativado.';
  END IF;
  IF target_account.status = _status THEN RETURN FALSE; END IF;

  UPDATE public.accounts
  SET status = _status,
      access_state_changed_at = now(),
      access_state_changed_by = _actor_user_id
  WHERE id = _account_id;

  INSERT INTO public.platform_audit_events(
    actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result, details
  ) VALUES (
    _actor_user_id,
    CASE WHEN _status = 'active' THEN 'account.activate' ELSE 'account.deactivate' END,
    'account', _account_id, _account_id, ARRAY['status'], 'success',
    jsonb_build_object('previous_status', target_account.status, 'new_status', _status, 'reason', normalized_reason)
  );
  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_client_dependency_counts(_actor_user_id uuid, _target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid; counts jsonb := '{}'::jsonb; n bigint; t record;
BEGIN
 IF coalesce(public.platform_admin_role_for(_actor_user_id)::text,'') <> 'super_admin' OR NOT EXISTS(SELECT 1 FROM public.accounts WHERE owner_user_id=_actor_user_id AND status='active' AND blocked_at IS NULL) THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF;
 SELECT id INTO aid FROM public.accounts WHERE owner_user_id=_target_user_id;
 IF aid IS NULL THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
 FOR t IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='account_id' AND table_name NOT IN ('admin_client_deletions','platform_audit_events','audit_events','account_access_events','account_members','user_roles','onboarding_tasks','access_grants','access_grant_events','profiles','specialties','appointment_types') LOOP
 EXECUTE format('SELECT count(*) FROM public.%I WHERE account_id=$1',t.table_name) INTO n USING aid;
 counts := counts || jsonb_build_object(t.table_name,n);
 END LOOP;
 SELECT count(*) INTO n FROM public.account_members WHERE account_id=aid AND user_id<>_target_user_id; counts:=counts||jsonb_build_object('other_members',n);
 SELECT count(*) INTO n FROM public.profiles WHERE account_id=aid AND id<>_target_user_id; counts:=counts||jsonb_build_object('other_profiles',n);
 SELECT count(*) INTO n FROM public.user_roles WHERE user_id=_target_user_id AND account_id<>aid; counts:=counts||jsonb_build_object('other_roles',n);
 SELECT count(*) INTO n FROM public.account_members WHERE user_id=_target_user_id AND account_id<>aid; counts:=counts||jsonb_build_object('other_memberships',n);
 SELECT count(*) INTO n FROM public.specialties WHERE account_id=aid AND (updated_at<>created_at OR NOT is_active OR name NOT IN ('Psicologia','Psicanálise','Neuropsicopedagogia','Psicopedagogia','Terapia','Neuropsicologia','Psiquiatria','Avaliação Psicológica','Orientação Profissional','Terapia Ocupacional','Fonoaudiologia','Nutrição','Serviço Social','Outra')); counts:=counts||jsonb_build_object('custom_specialties',n);
 SELECT count(*) INTO n FROM public.appointment_types WHERE account_id=aid AND (updated_at<>created_at OR NOT is_active OR description IS NOT NULL OR (name,default_duration_minutes,category) NOT IN (('Atendimento Clínico',50,'atendimento'),('Avaliação',90,'avaliacao'),('Devolutiva',50,'devolutiva'),('Reunião Externa',60,'reuniao'),('Entrevista Inicial',60,'avaliacao'),('Orientação',50,'atendimento'),('Supervisão',60,'atendimento'),('Acompanhamento',50,'atendimento'),('Reunião com Responsável',60,'reuniao'),('Reunião Escolar',60,'reuniao'),('Outro',60,'outro'))); counts:=counts||jsonb_build_object('custom_services',n);
 SELECT count(*) INTO n FROM public.help_events WHERE user_id=_target_user_id; counts:=counts||jsonb_build_object('help_events',n);
 SELECT count(*) INTO n FROM public.help_progress WHERE user_id=_target_user_id; counts:=counts||jsonb_build_object('help_progress',n);
 SELECT count(*) INTO n FROM storage.objects WHERE owner_id=_target_user_id::text OR split_part(name,'/',1) IN (_target_user_id::text,aid::text); counts:=counts||jsonb_build_object('files',n);
 RETURN counts;
END $function$

CREATE OR REPLACE FUNCTION public.admin_configure_billing(_actor_user_id uuid, _account_id uuid, _first_due_on date, _promo_price_cents integer DEFAULT NULL::integer, _promo_cycles integer DEFAULT NULL::integer, _regular_price_cents integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  offer public.subscription_plans%ROWTYPE;
  prev public.account_subscriptions%ROWTYPE;
  saved public.account_subscriptions%ROWTYPE;
  fields text[] := ARRAY['next_due_on'];
BEGIN
  PERFORM public.assert_billing_admin(_actor_user_id);
  IF _first_due_on IS NULL OR _first_due_on < (now() AT TIME ZONE 'America/Sao_Paulo')::date THEN
    RAISE EXCEPTION 'O vencimento não pode ser no passado.';
  END IF;
  PERFORM 1 FROM public.accounts WHERE id = _account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
  SELECT * INTO prev FROM public.account_subscriptions WHERE account_id = _account_id FOR UPDATE;

  IF prev.id IS NULL THEN
    IF EXISTS (SELECT 1 FROM public.access_grants WHERE account_id = _account_id AND kind = 'admin_trial' AND revoked_at IS NULL AND ends_at > now() AND NOT convertible) THEN
      RAISE EXCEPTION 'A degustação vigente foi marcada como não conversível.';
    END IF;
    SELECT * INTO offer FROM public.subscription_plans
    WHERE code = 'teraclini_mensal' AND is_active AND currency = 'BRL' AND billing_interval_months = 1 AND price_cents > 0;
    IF NOT FOUND THEN RAISE EXCEPTION 'O Plano Completo mensal está indisponível.'; END IF;
    INSERT INTO public.account_subscriptions(account_id, plan_id, contracted_price_cents, currency, starts_on, next_due_on, billing_period, status, promo_price_cents, promo_cycles, regular_price_cents, configured_by, configured_at)
    VALUES (_account_id, offer.id, offer.price_cents, offer.currency, _first_due_on, _first_due_on, date_trunc('month', _first_due_on)::date, 'awaiting_first_payment', offer.price_cents, 0, offer.price_cents, _actor_user_id, now())
    RETURNING * INTO saved;
    fields := fields || ARRAY['plan_id','status','promo_price_cents','promo_cycles','regular_price_cents','contracted_price_cents'];
  ELSE
    IF prev.status = 'cancelled' THEN RAISE EXCEPTION 'Reative a assinatura antes de alterar o vencimento.'; END IF;
    UPDATE public.account_subscriptions SET next_due_on = _first_due_on, billing_period = date_trunc('month', _first_due_on)::date,
      configured_by = _actor_user_id, configured_at = now(), updated_at = now()
    WHERE id = prev.id RETURNING * INTO saved;
  END IF;

  INSERT INTO public.access_grant_events(account_id, actor_user_id, action, previous_values, new_values)
  VALUES (_account_id, _actor_user_id, 'billing.configured',
    CASE WHEN prev.id IS NOT NULL THEN jsonb_build_object('next_due_on', prev.next_due_on, 'promo_price_cents', prev.promo_price_cents, 'promo_cycles', prev.promo_cycles, 'regular_price_cents', prev.regular_price_cents) END,
    jsonb_build_object('next_due_on', saved.next_due_on, 'promo_price_cents', saved.promo_price_cents, 'promo_cycles', saved.promo_cycles, 'regular_price_cents', saved.regular_price_cents));
  INSERT INTO public.subscription_events(subscription_id, account_id, actor_user_id, event_type, previous_status, new_status, changed_fields)
  VALUES (saved.id, _account_id, _actor_user_id, 'billing.configured', prev.status, saved.status, fields);
  INSERT INTO public.platform_audit_events(actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result)
  VALUES (_actor_user_id, 'billing.configure', 'subscription', saved.id, _account_id, fields, 'success');
  RETURN saved.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_confirm_payment(_actor_user_id uuid, _payment_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _admin_role public.platform_admin_role;
  _payment public.payments%ROWTYPE;
  _now TIMESTAMPTZ := now();
BEGIN
  SELECT role INTO _admin_role
  FROM public.platform_admins
  WHERE user_id = _actor_user_id AND revoked_at IS NULL;

  IF _admin_role IS NULL OR _admin_role NOT IN ('super_admin', 'finance_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  SELECT * INTO _payment FROM public.payments WHERE id = _payment_id FOR UPDATE;
  IF _payment.id IS NULL THEN RAISE EXCEPTION 'Pagamento não encontrado'; END IF;
  IF _payment.status = 'confirmed' THEN RETURN false; END IF;
  IF _payment.status IN ('refunded', 'cancelled') THEN
    RAISE EXCEPTION 'Este pagamento não pode ser confirmado';
  END IF;

  UPDATE public.payments SET
    status = 'confirmed', paid_at = _now, confirmed_at = _now,
    confirmed_by = _actor_user_id, confirmation_source = 'manual_admin'
  WHERE id = _payment.id;

  INSERT INTO public.payment_events (
    payment_id, account_id, actor_user_id, event_type,
    previous_status, new_status, amount_cents
  ) VALUES (
    _payment.id, _payment.account_id, _actor_user_id, 'manual_confirmation',
    _payment.status, 'confirmed', _payment.amount_cents
  );

  INSERT INTO public.platform_audit_events (
    actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result
  ) VALUES (
    _actor_user_id, 'payment.confirm', 'payment', _payment.id, _payment.account_id,
    ARRAY['status', 'paid_at', 'confirmed_at', 'confirmed_by', 'confirmation_source'], 'success'
  );

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_extend_access(_actor_user_id uuid, _account_id uuid, _days integer, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g public.access_grants%ROWTYPE; new_end timestamptz;
BEGIN
  PERFORM public.assert_billing_admin(_actor_user_id);
  IF _days IS NULL OR _days < 1 OR _days > 365 THEN RAISE EXCEPTION 'Prorrogação deve ficar entre 1 e 365 dias.'; END IF;
  IF coalesce(trim(_reason), '') = '' THEN RAISE EXCEPTION 'Informe o motivo da prorrogação.'; END IF;
  SELECT * INTO g FROM public.access_grants WHERE account_id = _account_id AND kind IN ('admin_trial','standard_trial') AND revoked_at IS NULL
  ORDER BY ends_at DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Nenhum período gratuito para prorrogar.'; END IF;
  new_end := greatest(g.ends_at, now()) + make_interval(days => _days);
  UPDATE public.access_grants SET ends_at = new_end, expired_at = NULL, updated_at = now() WHERE id = g.id;
  INSERT INTO public.access_grant_events(account_id, grant_id, actor_user_id, action, previous_values, new_values, reason)
  VALUES (_account_id, g.id, _actor_user_id, 'grant.extended', jsonb_build_object('ends_at', g.ends_at), jsonb_build_object('ends_at', new_end, 'days', _days), _reason);
  INSERT INTO public.platform_audit_events(actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result)
  VALUES (_actor_user_id, 'access.extend', 'access_grant', g.id, _account_id, ARRAY['ends_at'], 'success');
  PERFORM public.suppress_resolved_trial_notifications(_account_id);
  RETURN g.id;
END; $function$

CREATE OR REPLACE FUNCTION public.admin_finalize_client_deletion(_actor_user_id uuid, _target_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE job public.admin_client_deletions%ROWTYPE;
BEGIN
 IF coalesce(public.platform_admin_role_for(_actor_user_id)::text,'')<>'super_admin' OR NOT EXISTS(SELECT 1 FROM public.accounts WHERE owner_user_id=_actor_user_id AND status='active' AND blocked_at IS NULL) THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF;
 SELECT * INTO job FROM public.admin_client_deletions WHERE user_id=_target_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exclusão não preparada.'; END IF;
 IF job.stage='completed' THEN RETURN true; END IF;
 IF EXISTS(SELECT 1 FROM auth.users WHERE id=_target_user_id) OR EXISTS(SELECT 1 FROM public.profiles WHERE id=_target_user_id) THEN RAISE EXCEPTION 'Identidade ainda existe.'; END IF;
 DELETE FROM public.onboarding_tasks WHERE account_id=job.account_id;
 DELETE FROM public.user_roles WHERE account_id=job.account_id AND user_id=_target_user_id;
 DELETE FROM public.account_members WHERE account_id=job.account_id AND user_id=_target_user_id;
 DELETE FROM public.appointment_types WHERE account_id=job.account_id;
 DELETE FROM public.specialties WHERE account_id=job.account_id;
 UPDATE public.accounts SET name='Conta arquivada',block_reason='Identidade excluída; auditoria preservada',deleted_identity_at=now() WHERE id=job.account_id;
 UPDATE public.admin_client_deletions SET stage='completed',completed_at=now() WHERE user_id=_target_user_id;
 INSERT INTO public.platform_audit_events(actor_user_id,action,entity_type,entity_id,account_id,result,details) VALUES(_actor_user_id,'user.delete_completed','user',_target_user_id,job.account_id,'success','{"identityDeleted":true,"accountArchived":true}'::jsonb);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.admin_grant_trial(_actor_user_id uuid, _account_id uuid, _days integer, _starts_at timestamp with time zone, _reason text, _notes text, _convertible boolean, _billing_starts_on date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE prev public.access_grants%ROWTYPE; new_id uuid; s timestamptz := coalesce(_starts_at, now());
BEGIN
  PERFORM public.assert_billing_admin(_actor_user_id);
  IF _days IS NULL OR _days < 1 OR _days > 365 THEN RAISE EXCEPTION 'Duração deve ficar entre 1 e 365 dias.'; END IF;
  IF _reason NOT IN ('degustacao','demonstracao','parceria','cortesia') THEN RAISE EXCEPTION 'Motivo inválido.'; END IF;
  PERFORM 1 FROM public.accounts WHERE id = _account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
  FOR prev IN SELECT * FROM public.access_grants WHERE account_id = _account_id AND kind = 'admin_trial' AND revoked_at IS NULL LOOP
    UPDATE public.access_grants SET revoked_at = now(), updated_at = now() WHERE id = prev.id;
    INSERT INTO public.access_grant_events(account_id, grant_id, actor_user_id, action, previous_values, reason)
    VALUES (_account_id, prev.id, _actor_user_id, 'grant.replaced', jsonb_build_object('ends_at', prev.ends_at), 'Substituída por nova degustação');
  END LOOP;
  INSERT INTO public.access_grants(account_id, kind, starts_at, ends_at, reason, notes, convertible, billing_starts_on, created_by)
  VALUES (_account_id, 'admin_trial', s, s + make_interval(days => _days), _reason, nullif(trim(_notes), ''), coalesce(_convertible, true), _billing_starts_on, _actor_user_id)
  RETURNING id INTO new_id;
  INSERT INTO public.access_grant_events(account_id, grant_id, actor_user_id, action, new_values, reason)
  VALUES (_account_id, new_id, _actor_user_id, 'grant.admin_trial', jsonb_build_object('days', _days, 'starts_at', s, 'ends_at', s + make_interval(days => _days), 'convertible', _convertible, 'billing_starts_on', _billing_starts_on), _reason);
  INSERT INTO public.platform_audit_events(actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result)
  VALUES (_actor_user_id, 'access.grant_trial', 'access_grant', new_id, _account_id, ARRAY['ends_at','reason'], 'success');
  PERFORM public.suppress_resolved_trial_notifications(_account_id);
  RETURN new_id;
END; $function$

CREATE OR REPLACE FUNCTION public.admin_manage_subscription(_actor_user_id uuid, _account_id uuid, _action text, _plan_id uuid DEFAULT NULL::uuid, _days integer DEFAULT NULL::integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _admin_role public.platform_admin_role;
  _subscription public.account_subscriptions%ROWTYPE;
  _plan public.subscription_plans%ROWTYPE;
  _subscription_id uuid;
  _previous_status public.subscription_status;
  _next_status public.subscription_status;
  _changed_fields text[] := '{}';
  _now timestamptz := now();
BEGIN
  SELECT role INTO _admin_role FROM public.platform_admins WHERE user_id = _actor_user_id AND revoked_at IS NULL;
  IF _admin_role IS NULL OR _admin_role NOT IN ('super_admin', 'finance_admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE id = _account_id) THEN RAISE EXCEPTION 'Conta não encontrada'; END IF;
  IF _action = 'create' THEN
    PERFORM 1 FROM public.accounts WHERE id = _account_id FOR UPDATE;
  END IF;
  SELECT * INTO _subscription FROM public.account_subscriptions WHERE account_id = _account_id FOR UPDATE;

  IF _action = 'create' THEN
    IF _subscription.id IS NOT NULL THEN RAISE EXCEPTION 'Esta conta já possui uma licença'; END IF;
    SELECT * INTO _plan FROM public.subscription_plans WHERE id = _plan_id AND code = 'teraclini_mensal' AND is_active;
    IF NOT FOUND THEN RAISE EXCEPTION 'Selecione o Plano Completo vigente'; END IF;
    RETURN public.admin_configure_billing(_actor_user_id, _account_id, (_now AT TIME ZONE 'America/Sao_Paulo')::date + _plan.first_payment_days);
  END IF;

  IF _subscription.id IS NULL THEN RAISE EXCEPTION 'Licença não encontrada'; END IF;
  _subscription_id := _subscription.id;
  _previous_status := _subscription.status;
  _next_status := _subscription.status;
  CASE _action
    WHEN 'change_plan' THEN
      IF _plan_id IS NULL THEN RAISE EXCEPTION 'Selecione um plano'; END IF;
      SELECT * INTO _plan FROM public.subscription_plans WHERE id = _plan_id AND is_active;
      IF NOT FOUND THEN RAISE EXCEPTION 'Plano não encontrado'; END IF;
      UPDATE public.account_subscriptions SET plan_id = _plan.id WHERE id = _subscription_id;
      _changed_fields := ARRAY['plan_id'];
    WHEN 'activate', 'reactivate' THEN
      UPDATE public.account_subscriptions SET status = 'active', cancelled_at = NULL,
        cancellation_requested_at = NULL, restricted_at = NULL WHERE id = _subscription_id;
      _next_status := 'active';
      _changed_fields := ARRAY['status'];
    WHEN 'restrict' THEN
      UPDATE public.account_subscriptions SET status = 'restricted', restricted_at = _now WHERE id = _subscription_id;
      _next_status := 'restricted';
      _changed_fields := ARRAY['status', 'restricted_at'];
    WHEN 'cancel' THEN
      UPDATE public.account_subscriptions SET status = 'cancelled', cancellation_requested_at = _now,
        cancelled_at = _now, restricted_at = NULL WHERE id = _subscription_id;
      _next_status := 'cancelled';
      _changed_fields := ARRAY['status', 'cancelled_at'];
    WHEN 'extend' THEN
      IF _days IS NULL OR _days < 1 OR _days > 365 THEN RAISE EXCEPTION 'Prazo inválido'; END IF;
      UPDATE public.account_subscriptions SET next_due_on = next_due_on + _days WHERE id = _subscription_id;
      _changed_fields := ARRAY['next_due_on'];
    ELSE RAISE EXCEPTION 'Ação inválida';
  END CASE;
  INSERT INTO public.subscription_events(subscription_id, account_id, actor_user_id, event_type, previous_status, new_status, changed_fields)
  VALUES (_subscription_id, _account_id, _actor_user_id, _action, _previous_status, _next_status, _changed_fields);
  INSERT INTO public.platform_audit_events(actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result)
  VALUES (_actor_user_id, 'subscription.' || _action, 'subscription', _subscription_id, _account_id, _changed_fields, 'success');
  RETURN _subscription_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_prepare_client_deletion(_actor_user_id uuid, _target_user_id uuid, _confirmation text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a public.accounts%ROWTYPE; counts jsonb;
BEGIN
 IF coalesce(public.platform_admin_role_for(_actor_user_id)::text,'')<>'super_admin' OR _actor_user_id=_target_user_id THEN RAISE EXCEPTION 'Operação não autorizada.'; END IF;
 SELECT * INTO a FROM public.accounts WHERE owner_user_id=_target_user_id FOR UPDATE;
 IF NOT FOUND OR a.deleted_identity_at IS NOT NULL THEN RAISE EXCEPTION 'Conta não disponível.'; END IF;
 IF EXISTS(SELECT 1 FROM public.platform_admins WHERE user_id=_target_user_id) OR EXISTS(SELECT 1 FROM auth.users WHERE id=_target_user_id AND lower(email)='eduardocomplex@gmail.com') THEN RAISE EXCEPTION 'Identidade protegida.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=_target_user_id AND lower(email)=lower(trim(_confirmation))) THEN RAISE EXCEPTION 'Confirmação inválida.'; END IF;
 counts:=public.admin_client_dependency_counts(_actor_user_id,_target_user_id);
 IF EXISTS(SELECT 1 FROM jsonb_each_text(counts) WHERE value::bigint>0) THEN RAISE EXCEPTION 'Dados vinculados impedem a exclusão. Use a desativação.'; END IF;
 INSERT INTO public.admin_client_deletions(user_id,account_id,actor_user_id) VALUES(_target_user_id,a.id,_actor_user_id) ON CONFLICT(user_id) DO NOTHING;
 UPDATE public.accounts SET deletion_started_at=coalesce(deletion_started_at,now()),status='closed',blocked_at=coalesce(blocked_at,now()),block_reason='Exclusão individual em andamento',access_state_changed_by=_actor_user_id WHERE id=a.id;
 INSERT INTO public.platform_audit_events(actor_user_id,action,entity_type,entity_id,account_id,result) VALUES(_actor_user_id,'user.delete_prepared','user',_target_user_id,a.id,'success');
 RETURN a.id;
END $function$

