CREATE OR REPLACE FUNCTION public.admin_record_subscription_payment(_actor_user_id uuid, _account_id uuid, _paid_at timestamp with time zone, _method text, _transaction_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE sub public.account_subscriptions%ROWTYPE; cyc integer; amount integer; pay_id uuid;
BEGIN
  PERFORM public.assert_billing_admin(_actor_user_id);
  IF _method NOT IN ('pix','other') THEN RAISE EXCEPTION 'Forma de pagamento inválida.'; END IF;
  IF _paid_at IS NULL OR _paid_at > now() + interval '1 hour' THEN RAISE EXCEPTION 'Data de pagamento inválida.'; END IF;
  SELECT * INTO sub FROM public.account_subscriptions WHERE account_id = _account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Configure a cobrança antes de registrar pagamentos.'; END IF;
  IF sub.status = 'cancelled' THEN RAISE EXCEPTION 'Assinatura cancelada.'; END IF;
  SELECT coalesce(max(cycle_number), 0) + 1 INTO cyc FROM public.payments WHERE subscription_id = sub.id AND status = 'confirmed';
  amount := public.subscription_cycle_price(cyc, sub.promo_price_cents, sub.promo_cycles, sub.regular_price_cents);
  INSERT INTO public.payments(account_id, subscription_id, amount_cents, due_on, billing_period, paid_at, method, status, transaction_id, confirmation_source, confirmed_at, confirmed_by, cycle_number)
  VALUES (_account_id, sub.id, amount, sub.next_due_on, date_trunc('month', sub.next_due_on)::date, _paid_at, _method, 'confirmed', nullif(trim(_transaction_id), ''), 'admin_manual', now(), _actor_user_id, cyc)
  RETURNING id INTO pay_id;
  UPDATE public.account_subscriptions SET status = 'active', restricted_at = NULL,
    next_due_on = (sub.next_due_on + interval '1 month')::date, billing_period = date_trunc('month', sub.next_due_on + interval '1 month')::date,
    contracted_price_cents = public.subscription_cycle_price(cyc + 1, sub.promo_price_cents, sub.promo_cycles, sub.regular_price_cents), updated_at = now()
  WHERE id = sub.id;
  INSERT INTO public.subscription_events(subscription_id, account_id, actor_user_id, event_type, previous_status, new_status, changed_fields, note)
  VALUES (sub.id, _account_id, _actor_user_id, 'payment.confirmed', sub.status, 'active', ARRAY['next_due_on','status'], 'Ciclo ' || cyc);
  INSERT INTO public.access_grant_events(account_id, actor_user_id, action, new_values)
  VALUES (_account_id, _actor_user_id, 'payment.confirmed', jsonb_build_object('cycle', cyc, 'amount_cents', amount, 'paid_at', _paid_at));
  INSERT INTO public.platform_audit_events(actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result)
  VALUES (_actor_user_id, 'payment.record', 'payment', pay_id, _account_id, ARRAY['status'], 'success');
  PERFORM public.suppress_resolved_trial_notifications(_account_id);
  RETURN pay_id;
END; $function$

CREATE OR REPLACE FUNCTION public.admin_revoke_access_grant(_actor_user_id uuid, _account_id uuid, _reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g public.access_grants%ROWTYPE; n integer := 0;
BEGIN
  PERFORM public.assert_billing_admin(_actor_user_id);
  IF coalesce(trim(_reason), '') = '' THEN RAISE EXCEPTION 'Informe o motivo.'; END IF;
  FOR g IN SELECT * FROM public.access_grants WHERE account_id = _account_id AND kind IN ('admin_trial','legacy') AND revoked_at IS NULL FOR UPDATE LOOP
    UPDATE public.access_grants SET revoked_at = now(), updated_at = now() WHERE id = g.id;
    INSERT INTO public.access_grant_events(account_id, grant_id, actor_user_id, action, previous_values, reason)
    VALUES (_account_id, g.id, _actor_user_id, 'grant.revoked', jsonb_build_object('kind', g.kind, 'ends_at', g.ends_at), _reason);
    n := n + 1;
  END LOOP;
  IF n = 0 THEN RAISE EXCEPTION 'Nenhuma liberação gratuita vigente.'; END IF;
  INSERT INTO public.platform_audit_events(actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result)
  VALUES (_actor_user_id, 'access.revoke', 'account', _account_id, _account_id, ARRAY['revoked_at'], 'success');
  RETURN n;
END; $function$

CREATE OR REPLACE FUNCTION public.admin_set_account_block(_actor_user_id uuid, _account_id uuid, _blocked boolean, _reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role public.platform_admin_role;
  actor_account_status TEXT;
  actor_account_blocked_at TIMESTAMPTZ;
  target_account public.accounts%ROWTYPE;
  normalized_reason TEXT := nullif(btrim(_reason), '');
BEGIN
  SELECT pa.role, a.status, a.blocked_at
  INTO actor_role, actor_account_status, actor_account_blocked_at
  FROM public.platform_admins pa
  JOIN public.accounts a ON a.owner_user_id = pa.user_id
  WHERE pa.user_id = _actor_user_id AND pa.revoked_at IS NULL;

  IF actor_role IS NULL OR actor_role NOT IN ('super_admin', 'support_admin')
     OR actor_account_status <> 'active' OR actor_account_blocked_at IS NOT NULL THEN
    RAISE EXCEPTION 'Operação não autorizada.';
  END IF;
  IF _blocked AND normalized_reason IS NULL THEN RAISE EXCEPTION 'Informe a justificativa.'; END IF;

  SELECT a.* INTO target_account FROM public.accounts a WHERE a.id = _account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
  IF _blocked AND target_account.owner_user_id = _actor_user_id THEN
    RAISE EXCEPTION 'Você não pode bloquear sua própria conta administrativa.';
  END IF;
  IF _blocked AND EXISTS (
    SELECT 1 FROM public.platform_admins pa
    WHERE pa.user_id = target_account.owner_user_id
      AND pa.role = 'super_admin'
      AND pa.revoked_at IS NULL
  ) AND (SELECT count(*) FROM public.platform_admins WHERE role = 'super_admin' AND revoked_at IS NULL) <= 1 THEN
    RAISE EXCEPTION 'O último administrador master ativo não pode ser bloqueado.';
  END IF;
  IF (_blocked AND target_account.blocked_at IS NOT NULL)
     OR (NOT _blocked AND target_account.blocked_at IS NULL) THEN RETURN FALSE; END IF;

  UPDATE public.accounts
  SET blocked_at = CASE WHEN _blocked THEN now() ELSE NULL END,
      blocked_by = CASE WHEN _blocked THEN _actor_user_id ELSE NULL END,
      block_reason = CASE WHEN _blocked THEN normalized_reason ELSE NULL END,
      access_state_changed_at = now(),
      access_state_changed_by = _actor_user_id
  WHERE id = _account_id;

  INSERT INTO public.platform_audit_events(
    actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result, details
  ) VALUES (
    _actor_user_id,
    CASE WHEN _blocked THEN 'account.block' ELSE 'account.unblock' END,
    'account', _account_id, _account_id,
    ARRAY['blocked_at', 'blocked_by', 'block_reason'], 'success',
    jsonb_build_object('previous_blocked', target_account.blocked_at IS NOT NULL, 'new_blocked', _blocked, 'reason', normalized_reason)
  );
  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_account_status(_actor_user_id uuid, _account_id uuid, _status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role public.platform_admin_role;
  actor_account_status TEXT;
  target_account public.accounts%ROWTYPE;
BEGIN
  SELECT pa.role, a.status INTO actor_role, actor_account_status
  FROM public.platform_admins pa
  JOIN public.accounts a ON a.owner_user_id = pa.user_id
  WHERE pa.user_id = _actor_user_id AND pa.revoked_at IS NULL;

  IF actor_role IS NULL OR actor_role NOT IN ('super_admin', 'support_admin') OR actor_account_status <> 'active' THEN
    RAISE EXCEPTION 'Operação não autorizada.';
  END IF;
  IF _status NOT IN ('active', 'suspended') THEN RAISE EXCEPTION 'Situação inválida.'; END IF;

  SELECT a.* INTO target_account FROM public.accounts a WHERE a.id = _account_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
  IF _status = 'suspended' AND target_account.owner_user_id = _actor_user_id THEN
    RAISE EXCEPTION 'Você não pode suspender sua própria conta administrativa.';
  END IF;
  IF target_account.status = _status THEN RETURN FALSE; END IF;

  UPDATE public.accounts SET status = _status WHERE id = _account_id;
  INSERT INTO public.platform_audit_events(actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result)
  VALUES (_actor_user_id, CASE WHEN _status = 'active' THEN 'account.activate' ELSE 'account.suspend' END, 'account', _account_id, _account_id, ARRAY['status'], 'success');
  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_platform_role(_actor_user_id uuid, _target_user_id uuid, _role platform_admin_role)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role public.platform_admin_role;
  actor_status TEXT;
  actor_blocked_at TIMESTAMPTZ;
  current_admin public.platform_admins%ROWTYPE;
  target_account_id UUID;
BEGIN
  SELECT pa.role, a.status, a.blocked_at INTO actor_role, actor_status, actor_blocked_at
  FROM public.platform_admins pa
  JOIN public.accounts a ON a.owner_user_id = pa.user_id
  WHERE pa.user_id = _actor_user_id AND pa.revoked_at IS NULL;
  IF actor_role <> 'super_admin' OR actor_status <> 'active' OR actor_blocked_at IS NOT NULL THEN
    RAISE EXCEPTION 'Operação não autorizada.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('platform_admin_role_change'));
  SELECT * INTO current_admin FROM public.platform_admins WHERE user_id = _target_user_id FOR UPDATE;
  SELECT account_id INTO target_account_id FROM public.profiles WHERE id = _target_user_id;
  IF target_account_id IS NULL THEN RAISE EXCEPTION 'Usuário não encontrado.'; END IF;

  IF _role IS NULL THEN
    IF _target_user_id = _actor_user_id THEN
      RAISE EXCEPTION 'Transfira a administração antes de remover seu próprio acesso.';
    END IF;
    IF current_admin.role = 'super_admin' AND current_admin.revoked_at IS NULL
       AND (SELECT count(*) FROM public.platform_admins WHERE role = 'super_admin' AND revoked_at IS NULL) <= 1 THEN
      RAISE EXCEPTION 'O último administrador master não pode ser removido.';
    END IF;
    IF current_admin.id IS NULL OR current_admin.revoked_at IS NOT NULL THEN RETURN FALSE; END IF;
    UPDATE public.platform_admins SET revoked_at = now() WHERE id = current_admin.id;
  ELSE
    IF current_admin.id IS NOT NULL AND current_admin.role = _role AND current_admin.revoked_at IS NULL THEN RETURN FALSE; END IF;
    IF current_admin.role = 'super_admin' AND current_admin.revoked_at IS NULL AND _role <> 'super_admin'
       AND (SELECT count(*) FROM public.platform_admins WHERE role = 'super_admin' AND revoked_at IS NULL) <= 1 THEN
      RAISE EXCEPTION 'O último administrador master não pode perder esse papel.';
    END IF;
    INSERT INTO public.platform_admins(user_id, role, granted_by, revoked_at)
    VALUES (_target_user_id, _role, _actor_user_id, NULL)
    ON CONFLICT (user_id) DO UPDATE SET role = EXCLUDED.role, granted_by = EXCLUDED.granted_by, revoked_at = NULL;
  END IF;

  INSERT INTO public.platform_audit_events(
    actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result, details
  ) VALUES (
    _actor_user_id,
    CASE WHEN _role IS NULL THEN 'admin.revoke' ELSE 'admin.grant' END,
    'platform_admin', _target_user_id, target_account_id, ARRAY['role', 'revoked_at'], 'success',
    jsonb_build_object('previous_role', current_admin.role, 'new_role', _role)
  );
  RETURN TRUE;
END;
$function$

