    IF current_admin.role = 'super_admin' AND current_admin.revoked_at IS NULL AND parsed_role <> 'super_admin'
       AND (SELECT count(*) FROM public.platform_admins WHERE role = 'super_admin' AND revoked_at IS NULL) <= 1 THEN
