$function$

CREATE OR REPLACE FUNCTION public.admin_update_user_profile(_actor_user_id uuid, _target_user_id uuid, _full_name text, _profession text, _professional_registry text, _city text, _state text, _care_mode care_mode, _phone text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor_role public.platform_admin_role;
  target_account_id UUID;
  changed BOOLEAN;
  previous_profile JSONB;
  updated_profile JSONB;
BEGIN
  actor_role := public.platform_admin_role_for(_actor_user_id);
  IF actor_role IS NULL OR actor_role NOT IN ('super_admin', 'support_admin') THEN
    RAISE EXCEPTION 'Operação não autorizada.';
  END IF;
  IF length(btrim(_full_name)) < 2 THEN RAISE EXCEPTION 'Informe um nome válido.'; END IF;

  SELECT account_id,
         jsonb_build_object(
           'full_name', full_name,
           'profession', profession,
           'professional_registry', professional_registry,
           'city', city,
           'state', state,
           'care_mode', care_mode,
           'phone', phone
         )
    INTO target_account_id, previous_profile
  FROM public.profiles
  WHERE id = _target_user_id
  FOR UPDATE;
  IF target_account_id IS NULL THEN RAISE EXCEPTION 'Perfil não encontrado.'; END IF;

  UPDATE public.profiles
  SET full_name = btrim(_full_name),
      profession = nullif(btrim(_profession), ''),
      professional_registry = nullif(btrim(_professional_registry), ''),
      city = nullif(btrim(_city), ''),
      state = nullif(btrim(_state), ''),
      care_mode = _care_mode,
      phone = nullif(btrim(_phone), '')
  WHERE id = _target_user_id
    AND (full_name, profession, professional_registry, city, state, care_mode, phone)
      IS DISTINCT FROM
      (btrim(_full_name), nullif(btrim(_profession), ''), nullif(btrim(_professional_registry), ''), nullif(btrim(_city), ''), nullif(btrim(_state), ''), _care_mode, nullif(btrim(_phone), ''));
  changed := FOUND;

  IF changed THEN
    SELECT jsonb_build_object(
             'full_name', full_name,
             'profession', profession,
             'professional_registry', professional_registry,
             'city', city,
             'state', state,
             'care_mode', care_mode,
             'phone', phone
           )
      INTO updated_profile
    FROM public.profiles
    WHERE id = _target_user_id;

    INSERT INTO public.platform_audit_events(
      actor_user_id, action, entity_type, entity_id, account_id, changed_fields, result, details
    ) VALUES (
      _actor_user_id, 'user.profile_update', 'user', _target_user_id, target_account_id,
      ARRAY['full_name','profession','professional_registry','city','state','care_mode','phone'],
      'success', jsonb_build_object('previous', previous_profile, 'new', updated_profile)
    );
  END IF;
  RETURN changed;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_patient_registration(_request_id uuid, _existing_patient_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE target_request public.patient_registration_requests%ROWTYPE; result_patient_id UUID; owner_user_id UUID; duplicate_count INTEGER; intake JSONB; chosen_is_match BOOLEAN;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão inválida.'; END IF;
 SELECT * INTO target_request FROM public.patient_registration_requests WHERE id=_request_id FOR UPDATE;
 IF NOT FOUND OR NOT public.is_account_member(target_request.account_id) THEN RAISE EXCEPTION 'Solicitação não encontrada.'; END IF;
 IF target_request.status='approved' AND target_request.patient_id IS NOT NULL THEN RETURN target_request.patient_id; END IF;
 IF target_request.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Esta solicitação já foi revisada.'; END IF;
 SELECT a.owner_user_id INTO owner_user_id FROM public.accounts a WHERE a.id=target_request.account_id;
 SELECT count(*) INTO duplicate_count FROM public.patients p WHERE p.account_id=target_request.account_id AND (regexp_replace(COALESCE(p.cpf,''),'\D','','g')=regexp_replace(target_request.cpf,'\D','','g') OR (p.email IS NOT NULL AND lower(p.email)=lower(target_request.email)) OR (lower(p.full_name)=lower(target_request.full_name) AND p.birth_date=target_request.birth_date));
 IF _existing_patient_id IS NULL AND duplicate_count>0 THEN RAISE EXCEPTION 'Já encontramos um cadastro semelhante. Revise antes de aprovar.'; END IF;
 IF _existing_patient_id IS NOT NULL THEN
  SELECT EXISTS(SELECT 1 FROM public.patients p WHERE p.id=_existing_patient_id AND p.account_id=target_request.account_id AND (regexp_replace(COALESCE(p.cpf,''),'\D','','g')=regexp_replace(target_request.cpf,'\D','','g') OR (p.email IS NOT NULL AND lower(p.email)=lower(target_request.email)) OR (lower(p.full_name)=lower(target_request.full_name) AND p.birth_date=target_request.birth_date))) INTO chosen_is_match;
  IF NOT chosen_is_match THEN RAISE EXCEPTION 'O paciente escolhido não corresponde às duplicidades encontradas.'; END IF;
  SELECT p.id INTO result_patient_id FROM public.patients p WHERE p.id=_existing_patient_id AND p.account_id=target_request.account_id FOR UPDATE;
  UPDATE public.patients p SET birth_date=COALESCE(target_request.birth_date,p.birth_date),gender=COALESCE(NULLIF(target_request.gender,''),p.gender),phone=COALESCE(NULLIF(target_request.phone,''),p.phone),email=COALESCE(NULLIF(target_request.email,''),p.email),address=COALESCE(NULLIF(concat_ws(', ',NULLIF(target_request.street,''),NULLIF(target_request.address_number,''),NULLIF(target_request.address_complement,''),NULLIF(target_request.neighborhood,'')),''),p.address),street=COALESCE(NULLIF(target_request.street,''),p.street),city=COALESCE(NULLIF(target_request.city,''),p.city),state=COALESCE(NULLIF(target_request.state,''),p.state),cpf=COALESCE(NULLIF(target_request.cpf,''),p.cpf),postal_code=COALESCE(NULLIF(target_request.postal_code,''),p.postal_code),address_number=COALESCE(NULLIF(target_request.address_number,''),p.address_number),address_complement=COALESCE(NULLIF(target_request.address_complement,''),p.address_complement),neighborhood=COALESCE(NULLIF(target_request.neighborhood,''),p.neighborhood),marital_status=COALESCE(NULLIF(target_request.marital_status,''),p.marital_status),education=COALESCE(NULLIF(target_request.education,''),p.education),occupation=COALESCE(NULLIF(target_request.occupation,''),p.occupation) WHERE p.id=result_patient_id;
 ELSE
  INSERT INTO public.patients(account_id,user_id,full_name,age_group,birth_date,gender,phone,email,address,street,city,state,status,cpf,postal_code,address_number,address_complement,neighborhood,marital_status,education,occupation,registration_source) VALUES(target_request.account_id,owner_user_id,target_request.full_name,target_request.age_group,target_request.birth_date,target_request.gender,target_request.phone,target_request.email,concat_ws(', ',NULLIF(target_request.street,''),NULLIF(target_request.address_number,''),NULLIF(target_request.address_complement,''),NULLIF(target_request.neighborhood,'')),target_request.street,target_request.city,target_request.state,'avaliacao',target_request.cpf,target_request.postal_code,target_request.address_number,target_request.address_complement,target_request.neighborhood,target_request.marital_status,target_request.education,target_request.occupation,'pre_registration_link') RETURNING id INTO result_patient_id;
 END IF;
 IF target_request.age_group<>'adulto' AND target_request.guardian_name IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.guardians g WHERE g.patient_id=result_patient_id AND g.account_id=target_request.account_id) THEN INSERT INTO public.guardians(account_id,user_id,patient_id,full_name,relationship,phone,email,is_primary) VALUES(target_request.account_id,owner_user_id,result_patient_id,target_request.guardian_name,target_request.guardian_relationship,target_request.guardian_phone,target_request.guardian_email,true); END IF;
 intake:=jsonb_build_object('motivo_busca',target_request.therapy_reason,'terapia_anterior',target_request.previous_therapy,'detalhes_terapia_anterior',target_request.previous_therapy_details,'diagnostico_medico',target_request.medical_diagnosis,'detalhes_diagnostico',target_request.medical_diagnosis_details,'uso_medicamento',target_request.medication_use,'detalhes_medicamento',target_request.medication_details,'historico_familiar_saude_mental',target_request.family_mental_health,'detalhes_historico_familiar',target_request.family_mental_health_details,'contato_emergencia',jsonb_build_object('nome',target_request.emergency_name,'vinculo',target_request.emergency_relationship,'telefone',target_request.emergency_phone,'observacao',target_request.emergency_notes),'preferencia_pagamento',target_request.payment_preference,'origem',target_request.referral_source,'origem_outro',target_request.referral_source_other);
 IF NOT EXISTS(SELECT 1 FROM public.anamneses a WHERE a.patient_id=result_patient_id AND a.account_id=target_request.account_id AND a.template_key='pre_registration') THEN INSERT INTO public.anamneses(account_id,user_id,patient_id,title,template_key,content,is_completed) VALUES(target_request.account_id,owner_user_id,result_patient_id,'Informações do pré-cadastro','pre_registration',intake,true); END IF;
 UPDATE public.patient_registration_requests SET status='approved',patient_id=result_patient_id,reviewed_by=auth.uid(),reviewed_at=COALESCE(reviewed_at,now()),approved_at=now(),rejection_reason=NULL,updated_at=now() WHERE id=_request_id;
 INSERT INTO public.audit_events(account_id,actor_user_id,entity_type,entity_id,action,changed_fields) VALUES(target_request.account_id,auth.uid(),'patient_registration',_request_id,'approved',ARRAY['status','patient_id']);
 RETURN result_patient_id;
