CREATE OR REPLACE FUNCTION public.assert_billing_admin(_actor_user_id uuid, _read_only boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.platform_admin_role; st text;
BEGIN
  SELECT pa.role, a.status INTO r, st FROM public.platform_admins pa JOIN public.accounts a ON a.owner_user_id = pa.user_id
  WHERE pa.user_id = _actor_user_id AND pa.revoked_at IS NULL;
  IF r IS NULL OR st <> 'active' THEN RAISE EXCEPTION 'Operação não autorizada.'; END IF;
  IF _read_only AND r IN ('super_admin','finance_admin','support_admin') THEN RETURN; END IF;
  IF r NOT IN ('super_admin','finance_admin') THEN RAISE EXCEPTION 'Operação não autorizada.'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.check_appointment_conflict()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ends_at <= NEW.starts_at THEN RAISE EXCEPTION 'O horário final deve ser depois do horário inicial.'; END IF;
  IF TG_OP = 'UPDATE' AND (OLD.starts_at IS DISTINCT FROM NEW.starts_at OR OLD.ends_at IS DISTINCT FROM NEW.ends_at)
     AND (OLD.status IN ('realizado','em_andamento','falta','cancelado') OR OLD.starts_at < now()) THEN
    RAISE EXCEPTION 'Atendimentos históricos, concluídos ou em andamento não podem ser movimentados.';
  END IF;
  IF NEW.status = 'cancelado' THEN
    IF NEW.cancellation_reason IS NULL OR char_length(btrim(NEW.cancellation_reason)) < 3 THEN RAISE EXCEPTION 'Informe o motivo do cancelamento.'; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.starts_at IS NOT DISTINCT FROM NEW.starts_at AND OLD.ends_at IS NOT DISTINCT FROM NEW.ends_at
     AND OLD.location_id IS NOT DISTINCT FROM NEW.location_id AND OLD.room_id IS NOT DISTINCT FROM NEW.room_id
     AND OLD.modality IS NOT DISTINCT FROM NEW.modality AND OLD.status <> 'cancelado' THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM public.schedule_blocks b WHERE b.account_id=NEW.account_id AND b.starts_at < NEW.ends_at AND b.ends_at > NEW.starts_at AND (b.location_id IS NULL OR b.location_id=NEW.location_id) AND (b.room_id IS NULL OR b.room_id=NEW.room_id)) THEN
    RAISE EXCEPTION 'Este horário está bloqueado na agenda.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.availability_rules r WHERE r.account_id=NEW.account_id AND r.is_active) AND NOT EXISTS (
    SELECT 1 FROM public.availability_rules r WHERE r.account_id=NEW.account_id AND r.is_active
      AND r.weekday=extract(dow FROM NEW.starts_at AT TIME ZONE r.timezone)::smallint
      AND (NEW.starts_at AT TIME ZONE r.timezone)::date = (NEW.ends_at AT TIME ZONE r.timezone)::date
      AND (NEW.starts_at AT TIME ZONE r.timezone)::time >= r.start_time
      AND (NEW.ends_at AT TIME ZONE r.timezone)::time <= r.end_time
      AND (r.valid_from IS NULL OR (NEW.starts_at AT TIME ZONE r.timezone)::date >= r.valid_from)
      AND (r.valid_until IS NULL OR (NEW.starts_at AT TIME ZONE r.timezone)::date <= r.valid_until)
      AND (r.location_id IS NULL OR r.location_id=NEW.location_id)
      AND (r.room_id IS NULL OR r.room_id=NEW.room_id)
      AND (r.modality IS NULL OR r.modality=NEW.modality)
  ) THEN RAISE EXCEPTION 'Este horário está fora da disponibilidade configurada.'; END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.complete_onboarding_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE key_name TEXT; target_account UUID;
BEGIN
  target_account := NEW.account_id;
  IF TG_TABLE_NAME='locations' THEN key_name := 'location';
  ELSIF TG_TABLE_NAME='rooms' THEN key_name := 'room';
  ELSIF TG_TABLE_NAME='availability_rules' THEN key_name := 'availability';
  ELSIF TG_TABLE_NAME='patients' THEN key_name := 'patient';
  ELSIF TG_TABLE_NAME='appointments' THEN key_name := 'appointment';
  END IF;
  IF key_name IS NOT NULL THEN UPDATE public.onboarding_tasks SET completed_at=COALESCE(completed_at,now()) WHERE account_id=target_account AND task_key=key_name; END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.create_professional_receivable(_appointment_id uuid DEFAULT NULL::uuid, _package_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a public.appointments%ROWTYPE; p public.care_packages%ROWTYPE; result uuid; amount bigint; pos integer;
BEGIN
 IF _appointment_id IS NOT NULL THEN
 SELECT * INTO a FROM public.appointments WHERE id=_appointment_id FOR UPDATE;
 IF a.id IS NULL OR a.patient_id IS NULL THEN RETURN NULL; END IF;
 SELECT id INTO result FROM public.professional_receivables WHERE appointment_id=a.id; IF result IS NOT NULL THEN RETURN result; END IF;
 IF a.package_id IS NULL THEN
 IF a.price_cents_snapshot IS NULL THEN RETURN NULL; END IF;
 INSERT INTO public.professional_receivables(account_id,patient_id,appointment_type_id,appointment_id,origin,amount_cents,due_on,service_name_snapshot,modality,created_by) VALUES(a.account_id,a.patient_id,a.appointment_type_id,a.id,'one_off',a.price_cents_snapshot,(a.starts_at AT TIME ZONE 'America/Sao_Paulo')::date,coalesce(a.service_name_snapshot,'Atendimento'),a.modality::text,a.user_id) RETURNING id INTO result;
 ELSE
 SELECT * INTO p FROM public.care_packages WHERE id=a.package_id FOR UPDATE;
 IF p.finance_mode='prepaid' THEN RETURN public.create_professional_receivable(NULL,p.id); END IF;
 IF p.finance_mode<>'per_session' OR p.total_value_cents IS NULL THEN RETURN NULL; END IF;
 SELECT count(*) INTO pos FROM public.professional_receivables WHERE package_id=p.id AND origin='package_session';
 IF pos>=p.quantity THEN RAISE EXCEPTION 'Todas as parcelas deste pacote já foram vinculadas. Reagende uma sessão existente.'; END IF;
 amount:=p.total_value_cents/p.quantity+CASE WHEN pos < p.total_value_cents%p.quantity THEN 1 ELSE 0 END;
 INSERT INTO public.professional_receivables(account_id,patient_id,appointment_type_id,appointment_id,package_id,origin,amount_cents,due_on,service_name_snapshot,modality,created_by) VALUES(a.account_id,a.patient_id,p.appointment_type_id,a.id,p.id,'package_session',amount,(a.starts_at AT TIME ZONE 'America/Sao_Paulo')::date,coalesce(p.service_name_snapshot,'Pacote'),a.modality::text,a.user_id) RETURNING id INTO result;
 END IF;
 ELSE
 SELECT * INTO p FROM public.care_packages WHERE id=_package_id FOR UPDATE;
 IF p.id IS NULL OR p.finance_mode<>'prepaid' OR p.total_value_cents IS NULL THEN RETURN NULL; END IF;
 SELECT id INTO result FROM public.professional_receivables WHERE package_id=p.id AND origin='package'; IF result IS NOT NULL THEN RETURN result; END IF;
 INSERT INTO public.professional_receivables(account_id,patient_id,appointment_type_id,package_id,origin,amount_cents,due_on,service_name_snapshot,modality,created_by) VALUES(p.account_id,p.patient_id,p.appointment_type_id,p.id,'package',p.total_value_cents,p.start_date,coalesce(p.service_name_snapshot,'Pacote'),p.scheduled_modality::text,p.user_id) RETURNING id INTO result;
 END IF; RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.create_support_ticket(_subject text, _message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  _ticket_id uuid;
  _account_id uuid;
BEGIN
  _account_id := public.current_account_id();
  IF _account_id IS NULL THEN RAISE EXCEPTION 'Active account required'; END IF;
  IF char_length(trim(_subject)) NOT BETWEEN 3 AND 160 THEN RAISE EXCEPTION 'Invalid subject'; END IF;
  IF char_length(trim(_message)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Invalid message'; END IF;
  INSERT INTO public.support_tickets(account_id, user_id, subject)
  VALUES (_account_id, auth.uid(), trim(_subject)) RETURNING id INTO _ticket_id;
  INSERT INTO public.support_messages(ticket_id, account_id, author_user_id, author_type, message)
  VALUES (_ticket_id, _account_id, auth.uid(), 'professional', trim(_message));
  RETURN _ticket_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.finance_import_contract(_appointment_id uuid DEFAULT NULL::uuid, _package_id uuid DEFAULT NULL::uuid, _mode text DEFAULT 'prepaid'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid; p public.care_packages%ROWTYPE; result uuid; a record;
BEGIN
 IF _appointment_id IS NOT NULL THEN SELECT account_id INTO aid FROM public.appointments WHERE id=_appointment_id; ELSE SELECT * INTO p FROM public.care_packages WHERE id=_package_id FOR UPDATE; aid:=p.account_id; END IF;
 IF NOT coalesce(public.can_manage_professional_finance(aid),false) THEN RAISE EXCEPTION 'Sem permissão financeira.'; END IF;
 IF _appointment_id IS NOT NULL THEN RETURN public.create_professional_receivable(_appointment_id,NULL); END IF;
 IF _mode NOT IN ('prepaid','per_session') OR p.total_value_cents IS NULL THEN RAISE EXCEPTION 'Defina o valor do contrato antes de incluir no financeiro.'; END IF;
 IF p.finance_mode='none' THEN UPDATE public.care_packages SET finance_mode=_mode WHERE id=p.id; ELSIF p.finance_mode<>_mode THEN RAISE EXCEPTION 'Modelo financeiro já definido.'; END IF;
 IF _mode='prepaid' THEN RETURN public.create_professional_receivable(NULL,p.id); END IF;
 FOR a IN SELECT id FROM public.appointments WHERE package_id=p.id ORDER BY starts_at,id LOOP result:=public.create_professional_receivable(a.id,NULL); END LOOP; RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.finance_lookup(_kind text, _search text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ DECLARE aid uuid:=public.current_account_id(); result jsonb; BEGIN IF NOT coalesce(public.can_manage_professional_finance(aid),false) THEN RAISE EXCEPTION 'Sem permissão financeira.'; END IF;
 IF _kind='patients' THEN SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') INTO result FROM(SELECT id,full_name AS name FROM public.patients WHERE account_id=aid AND full_name ILIKE '%'||left(_search,100)||'%' ORDER BY full_name LIMIT 20) s;
 ELSIF _kind='services' THEN SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') INTO result FROM(SELECT id,name FROM public.appointment_types WHERE account_id=aid AND is_active AND name ILIKE '%'||left(_search,100)||'%' ORDER BY name LIMIT 30) s;
 ELSIF _kind='packages' THEN SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') INTO result FROM(SELECT c.id,p.full_name||' · '||c.quantity||' sessões' AS name FROM public.care_packages c JOIN public.patients p ON p.id=c.patient_id WHERE c.account_id=aid AND p.full_name ILIKE '%'||left(_search,100)||'%' ORDER BY c.created_at DESC LIMIT 20) s;
 ELSE RAISE EXCEPTION 'Consulta inválida.'; END IF; RETURN result; END $function$

CREATE OR REPLACE FUNCTION public.finance_query(_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid:=public.current_account_id(); page integer:=greatest(1,coalesce((_filters->>'page')::integer,1)); size integer:=least(100,greatest(1,coalesce((_filters->>'page_size')::integer,20))); result jsonb;
BEGIN
 IF NOT coalesce(public.can_manage_professional_finance(aid),false) THEN RAISE EXCEPTION 'Sem permissão financeira.'; END IF;
 WITH base AS (
 SELECT t.*,p.full_name AS patient_name,coalesce(x.paid,0) AS received_cents,greatest(t.amount_cents-coalesce(x.paid,0),0) AS balance_cents,CASE WHEN t.cancelled_at IS NOT NULL THEN 'cancelled' WHEN coalesce(x.paid,0)>=t.amount_cents THEN 'paid' WHEN coalesce(x.paid,0)>0 THEN 'partial' ELSE 'pending' END AS status
 FROM public.professional_receivables t JOIN public.patients p ON p.id=t.patient_id LEFT JOIN LATERAL(SELECT sum(r.amount_cents) AS paid FROM public.professional_receipts r WHERE r.receivable_id=t.id AND r.status='confirmed') x ON true
 WHERE t.account_id=aid AND (nullif(_filters->>'patient_id','') IS NULL OR t.patient_id=(_filters->>'patient_id')::uuid) AND (nullif(_filters->>'service_id','') IS NULL OR t.appointment_type_id=(_filters->>'service_id')::uuid) AND (nullif(_filters->>'package_id','') IS NULL OR t.package_id=(_filters->>'package_id')::uuid) AND (nullif(_filters->>'appointment_id','') IS NULL OR t.appointment_id=(_filters->>'appointment_id')::uuid OR t.package_id=(SELECT package_id FROM public.appointments WHERE id=(_filters->>'appointment_id')::uuid AND account_id=aid)) AND (nullif(_filters->>'modality','') IS NULL OR t.modality=_filters->>'modality') AND (coalesce(_filters->>'packages_only','false')<>'true' OR t.package_id IS NOT NULL)
 ), titles AS (
 SELECT * FROM base t WHERE (nullif(_filters->>'from','') IS NULL OR t.due_on>=(_filters->>'from')::date) AND (nullif(_filters->>'to','') IS NULL OR t.due_on<=(_filters->>'to')::date) AND (nullif(_filters->>'status','') IS NULL OR t.status=_filters->>'status') AND (coalesce(_filters->>'pending_only','false')<>'true' OR t.status IN ('pending','partial')) AND (nullif(_filters->>'method','') IS NULL OR EXISTS(SELECT 1 FROM public.professional_receipts r WHERE r.receivable_id=t.id AND r.method=_filters->>'method'))
 ), receipts AS (
 SELECT r.*,b.patient_id,b.patient_name,b.service_name_snapshot,b.package_id,b.appointment_id,b.modality FROM public.professional_receipts r JOIN base b ON b.id=r.receivable_id WHERE r.account_id=aid AND (nullif(_filters->>'from','') IS NULL OR r.received_on>=(_filters->>'from')::date) AND (nullif(_filters->>'to','') IS NULL OR r.received_on<=(_filters->>'to')::date) AND (nullif(_filters->>'method','') IS NULL OR r.method=_filters->>'method') AND (nullif(_filters->>'receipt_status','') IS NULL OR r.status=_filters->>'receipt_status')
 )
 SELECT jsonb_build_object('rows',CASE WHEN _filters->>'view'='receipts' THEN coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM (SELECT * FROM receipts ORDER BY received_on DESC,id LIMIT size OFFSET (page-1)*size) s),'[]'::jsonb) ELSE coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM (SELECT * FROM titles ORDER BY due_on DESC,id LIMIT size OFFSET (page-1)*size) s),'[]'::jsonb) END,'total',CASE WHEN _filters->>'view'='receipts' THEN (SELECT count(*) FROM receipts) ELSE (SELECT count(*) FROM titles) END,'summary',jsonb_build_object('received_cents',(SELECT coalesce(sum(amount_cents),0) FROM receipts WHERE status='confirmed'),'pending_cents',(SELECT coalesce(sum(balance_cents),0) FROM titles WHERE status IN ('pending','partial')),'partial_cents',(SELECT coalesce(sum(balance_cents),0) FROM titles WHERE status='partial'),'cancelled_cents',(SELECT coalesce(sum(amount_cents),0) FROM titles WHERE status='cancelled'),'confirmed_count',(SELECT count(*) FROM receipts WHERE status='confirmed'),'pending_count',(SELECT count(*) FROM titles WHERE status IN ('pending','partial')),'active_packages',(SELECT count(*) FROM public.care_packages WHERE account_id=aid AND lifecycle_status='ativo'))) INTO result;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.finance_receipt_action(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE action text:=_payload->>'action'; r public.professional_receipts%ROWTYPE; t public.professional_receivables%ROWTYPE; rid uuid; amount bigint; paid bigint; target_status text; key uuid; received date; payment_method text;
BEGIN
 IF action='create' THEN SELECT * INTO t FROM public.professional_receivables WHERE id=(_payload->>'receivable_id')::uuid FOR UPDATE;
 ELSE SELECT * INTO r FROM public.professional_receipts WHERE id=(_payload->>'id')::uuid; SELECT * INTO t FROM public.professional_receivables WHERE id=r.receivable_id FOR UPDATE; SELECT * INTO r FROM public.professional_receipts WHERE id=r.id FOR UPDATE; END IF;
 IF t.id IS NULL OR NOT coalesce(public.can_manage_professional_finance(t.account_id),false) THEN RAISE EXCEPTION 'Título não encontrado ou sem permissão.'; END IF;
 IF action='create' THEN key:=(_payload->>'request_key')::uuid; IF key IS NULL THEN RAISE EXCEPTION 'Identificador obrigatório.'; END IF; SELECT id INTO rid FROM public.professional_receipts WHERE account_id=t.account_id AND request_key=key; IF rid IS NOT NULL THEN RETURN rid; END IF; target_status:=CASE WHEN coalesce((_payload->>'confirmed')::boolean,false) THEN 'confirmed' ELSE 'pending' END;
 ELSIF action='confirm' THEN IF r.status<>'pending' THEN RAISE EXCEPTION 'Somente um recebimento pendente pode ser confirmado.'; END IF; target_status:='confirmed';
 ELSIF action='reverse' THEN IF r.status<>'confirmed' THEN RAISE EXCEPTION 'Somente um recebimento confirmado pode ser estornado.'; END IF; target_status:='reversed';
 ELSIF action='cancel' THEN IF r.status<>'pending' THEN RAISE EXCEPTION 'Somente um recebimento pendente pode ser cancelado.'; END IF; target_status:='cancelled';
 ELSIF action='edit' THEN IF r.status NOT IN ('pending','confirmed') THEN RAISE EXCEPTION 'Movimento encerrado não pode ser editado.'; END IF; target_status:=r.status;
 ELSE RAISE EXCEPTION 'Ação inválida.'; END IF;
 amount:=coalesce((_payload->>'amount_cents')::bigint,r.amount_cents); received:=coalesce((_payload->>'received_on')::date,r.received_on); payment_method:=coalesce(_payload->>'method',r.method);
 IF amount IS NULL OR amount<=0 OR amount>2147483647 OR received IS NULL OR payment_method IS NULL OR payment_method NOT IN ('pix','card','cash','transfer','other') THEN RAISE EXCEPTION 'Revise valor, data e forma de pagamento.'; END IF;
 IF t.cancelled_at IS NOT NULL AND target_status IN ('pending','confirmed') THEN RAISE EXCEPTION 'Título cancelado não recebe pagamentos.'; END IF;
 SELECT coalesce(sum(amount_cents),0) INTO paid FROM public.professional_receipts WHERE receivable_id=t.id AND status='confirmed' AND (r.id IS NULL OR id<>r.id);
 IF target_status='confirmed' AND paid+amount>t.amount_cents THEN RAISE EXCEPTION 'O recebimento ultrapassa o saldo contratado.'; END IF;
 IF action='create' THEN INSERT INTO public.professional_receipts(account_id,receivable_id,amount_cents,received_on,method,status,note,request_key,created_by,confirmed_by,confirmed_at) VALUES(t.account_id,t.id,amount,received,payment_method,target_status,left(_payload->>'note',1000),key,auth.uid(),CASE WHEN target_status='confirmed' THEN auth.uid() END,CASE WHEN target_status='confirmed' THEN now() END) RETURNING id INTO rid;
 ELSE UPDATE public.professional_receipts SET amount_cents=amount,received_on=received,method=payment_method,status=target_status,note=CASE WHEN _payload ? 'note' THEN left(_payload->>'note',1000) ELSE note END,confirmed_at=CASE WHEN target_status='confirmed' THEN coalesce(confirmed_at,now()) ELSE confirmed_at END,confirmed_by=CASE WHEN target_status='confirmed' THEN coalesce(confirmed_by,auth.uid()) ELSE confirmed_by END,updated_at=now() WHERE id=r.id RETURNING id INTO rid; END IF; RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION public.get_attendance_pricing()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid := public.current_account_id(); r public.account_attendance_pricing%ROWTYPE;
BEGIN
  IF aid IS NULL THEN RAISE EXCEPTION 'Conta indisponível.'; END IF;
