END $function$

CREATE OR REPLACE FUNCTION public.guard_client_deletion_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid; started timestamptz;
BEGIN
 aid := NEW.account_id;
 SELECT deletion_started_at INTO started FROM public.accounts WHERE id=aid FOR SHARE;
