CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  new_account_id UUID;
  profile_name TEXT;
  profile_avatar TEXT;
BEGIN
  profile_name := COALESCE(
    NULLIF(BTRIM(NEW.raw_user_meta_data ->> 'full_name'), ''),
    NULLIF(BTRIM(NEW.raw_user_meta_data ->> 'name'), ''),
    ''
  );
  profile_avatar := COALESCE(
    NULLIF(BTRIM(NEW.raw_user_meta_data ->> 'avatar_url'), ''),
    NULLIF(BTRIM(NEW.raw_user_meta_data ->> 'picture'), '')
  );

  INSERT INTO public.accounts (owner_user_id, name)
  VALUES (NEW.id, COALESCE(NULLIF(profile_name, ''), 'Meu espaço profissional'))
  RETURNING id INTO new_account_id;

  INSERT INTO public.account_members (account_id, user_id, status)
  VALUES (new_account_id, NEW.id, 'active');

  INSERT INTO public.user_roles (account_id, user_id, role)
  VALUES (new_account_id, NEW.id, 'owner');

  INSERT INTO public.profiles (id, account_id, full_name, avatar_url)
  VALUES (NEW.id, new_account_id, profile_name, profile_avatar)
  ON CONFLICT (id) DO UPDATE SET account_id = EXCLUDED.account_id;

  INSERT INTO public.onboarding_tasks (account_id, task_key)
  SELECT new_account_id, task_key
  FROM unnest(ARRAY['profile', 'location', 'room', 'availability', 'patient', 'appointment']) AS task_key;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_trial_lifecycle(_source text DEFAULT 'schedule'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  g public.access_grants%ROWTYPE; st text; n integer; day5 integer := 0; ended integer := 0;
  expired integer := 0; fails integer := 0; errs jsonb := '[]'::jsonb; run_id uuid; res jsonb; offer_message text;
BEGIN
  SELECT format(' Novas assinaturas do %s: R$ %s por mês, sem aumento automático por ciclo. A contratação é concluída com a equipe TeraClini.',
    name, replace(to_char(price_cents::numeric / 100, 'FM9999999990.00'), '.', ','))
  INTO offer_message FROM public.subscription_plans
  WHERE code = 'teraclini_mensal' AND is_active AND currency = 'BRL' AND billing_interval_months = 1 AND price_cents > 0;
  INSERT INTO public.subscription_job_runs(trigger_source) VALUES (coalesce(_source, 'schedule')) RETURNING id INTO run_id;
  FOR g IN SELECT * FROM public.access_grants WHERE kind = 'standard_trial' AND revoked_at IS NULL AND starts_at + interval '5 days' <= now() LOOP
    BEGIN
      st := public.account_commercial_state(g.account_id);
      IF st = 'trial' AND now() < g.ends_at THEN
        INSERT INTO public.professional_notifications(account_id, event_key, kind, title, body, action_path)
        VALUES (g.account_id, 'trial_day5:' || g.id, 'trial_day5', 'Seu período de degustação está terminando',
          'Seu teste gratuito da TeraClini está chegando ao fim. Consulte as condições da sua assinatura no portal.' ||
          CASE WHEN EXISTS (SELECT 1 FROM public.account_subscriptions s WHERE s.account_id = g.account_id) THEN '' ELSE coalesce(offer_message, '') END,
          '/assinatura')
        ON CONFLICT (event_key) DO NOTHING;
        GET DIAGNOSTICS n = ROW_COUNT; day5 := day5 + n;
      ELSIF st = 'awaiting_contract' AND now() >= g.ends_at THEN
        INSERT INTO public.professional_notifications(account_id, event_key, kind, title, body, action_path)
        VALUES (g.account_id, 'trial_ended:' || g.id || ':' || to_char(g.ends_at, 'YYYYMMDDHH24MISS'), 'trial_ended', 'Seu período gratuito terminou',
          'Seu período gratuito da TeraClini terminou. Para continuar utilizando o sistema, conclua a contratação da sua assinatura. Seus dados permanecem preservados de acordo com a política de retenção da plataforma.' ||
          CASE WHEN EXISTS (SELECT 1 FROM public.account_subscriptions s WHERE s.account_id = g.account_id) THEN '' ELSE coalesce(offer_message, '') END,
          '/assinatura')
        ON CONFLICT (event_key) DO NOTHING;
        GET DIAGNOSTICS n = ROW_COUNT; ended := ended + n;
        IF g.expired_at IS NULL THEN
          UPDATE public.access_grants SET expired_at = now(), updated_at = now() WHERE id = g.id;
          INSERT INTO public.access_grant_events(account_id, grant_id, action, new_values) VALUES (g.account_id, g.id, 'trial.expired', jsonb_build_object('ends_at', g.ends_at));
          expired := expired + 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      fails := fails + 1; errs := errs || jsonb_build_object('grant_id', g.id, 'error', SQLERRM);
    END;
  END LOOP;
  UPDATE public.professional_notifications pn SET suppressed_at = now()
  WHERE pn.kind IN ('trial_day5','trial_ended') AND pn.suppressed_at IS NULL
    AND public.account_commercial_state(pn.account_id) IN ('active','payment_pending','legacy','admin_trial');
  res := jsonb_build_object('day5_created', day5, 'ended_created', ended, 'expired', expired, 'errors', errs);
  UPDATE public.subscription_job_runs SET finished_at = now(), result = res, failures = fails WHERE id = run_id;
  RETURN res;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_appointment_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE event_name TEXT; fields TEXT[] := '{}';
BEGIN
  IF TG_OP='INSERT' THEN event_name := 'criado'; fields := ARRAY['starts_at','ends_at','status'];
  ELSE
    IF OLD.starts_at IS DISTINCT FROM NEW.starts_at OR OLD.ends_at IS DISTINCT FROM NEW.ends_at THEN event_name := 'reagendado'; fields := array_append(fields,'starts_at'); fields := array_append(fields,'ends_at');
    ELSIF OLD.status IS DISTINCT FROM NEW.status THEN
      event_name := CASE NEW.status WHEN 'confirmado' THEN 'confirmado' WHEN 'em_andamento' THEN 'iniciado' WHEN 'realizado' THEN 'concluido' WHEN 'cancelado' THEN 'cancelado' WHEN 'falta' THEN 'falta' ELSE 'atualizado' END;
      fields := array_append(fields,'status');
    ELSE event_name := 'atualizado'; END IF;
    IF OLD.location_id IS DISTINCT FROM NEW.location_id THEN fields := array_append(fields,'location_id'); END IF;
    IF OLD.room_id IS DISTINCT FROM NEW.room_id THEN fields := array_append(fields,'room_id'); END IF;
    IF OLD.patient_id IS DISTINCT FROM NEW.patient_id THEN fields := array_append(fields,'patient_id'); END IF;
  END IF;
  INSERT INTO public.appointment_events(account_id,appointment_id,actor_user_id,event_type,previous_starts_at,previous_ends_at,new_starts_at,new_ends_at,reason,changed_fields)
  VALUES(NEW.account_id,NEW.id,auth.uid(),event_name,CASE WHEN TG_OP='UPDATE' THEN OLD.starts_at END,CASE WHEN TG_OP='UPDATE' THEN OLD.ends_at END,NEW.starts_at,NEW.ends_at,NEW.cancellation_reason,fields);
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.record_care_package_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  event_name TEXT;
  fields TEXT[] := '{}';
BEGIN
  IF TG_OP = 'INSERT' THEN
    event_name := CASE WHEN NEW.parent_package_id IS NULL THEN 'criado' ELSE 'renovado' END;
    fields := ARRAY['quantity', 'start_date', 'lifecycle_status'];
  ELSE
    IF OLD.lifecycle_status IS DISTINCT FROM NEW.lifecycle_status AND NEW.lifecycle_status = 'cancelado' THEN
      event_name := 'cancelado';
    ELSIF OLD.lifecycle_status IS DISTINCT FROM NEW.lifecycle_status AND NEW.lifecycle_status = 'encerrado' THEN
      event_name := 'encerrado';
    ELSE
      event_name := 'alterado';
    END IF;
    IF OLD.quantity IS DISTINCT FROM NEW.quantity THEN fields := array_append(fields, 'quantity'); END IF;
    IF OLD.total_value IS DISTINCT FROM NEW.total_value THEN fields := array_append(fields, 'total_value'); END IF;
    IF OLD.value_per_session IS DISTINCT FROM NEW.value_per_session THEN fields := array_append(fields, 'value_per_session'); END IF;
    IF OLD.start_date IS DISTINCT FROM NEW.start_date THEN fields := array_append(fields, 'start_date'); END IF;
    IF OLD.end_date IS DISTINCT FROM NEW.end_date THEN fields := array_append(fields, 'end_date'); END IF;
    IF OLD.periodicity IS DISTINCT FROM NEW.periodicity THEN fields := array_append(fields, 'periodicity'); END IF;
    IF OLD.renewal_alert_threshold IS DISTINCT FROM NEW.renewal_alert_threshold THEN fields := array_append(fields, 'renewal_alert_threshold'); END IF;
    IF OLD.lifecycle_status IS DISTINCT FROM NEW.lifecycle_status THEN fields := array_append(fields, 'lifecycle_status'); END IF;
  END IF;
  INSERT INTO public.care_package_events(account_id, package_id, actor_user_id, event_type, changed_fields, related_package_id)
  VALUES (NEW.account_id, NEW.id, auth.uid(), event_name, fields, NEW.parent_package_id);
  RETURN NEW;
END;
$function$

