CREATE OR REPLACE FUNCTION public.record_safe_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  row_id UUID;
  row_account_id UUID;
  fields TEXT[] := '{}';
  event_action TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    row_id := OLD.id;
    row_account_id := OLD.account_id;
    event_action := 'deleted';
  ELSE
    row_id := NEW.id;
    row_account_id := NEW.account_id;
    event_action := CASE WHEN TG_OP = 'INSERT' THEN 'created' ELSE 'updated' END;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT COALESCE(array_agg(key ORDER BY key), '{}') INTO fields
    FROM jsonb_each(to_jsonb(NEW)) n
    WHERE key NOT IN ('content', 'notes', 'storage_path', 'cpf', 'phone', 'email', 'address')
      AND to_jsonb(OLD) -> key IS DISTINCT FROM n.value;
  END IF;

  INSERT INTO public.audit_events (account_id, actor_user_id, entity_type, entity_id, action, changed_fields)
  VALUES (row_account_id, auth.uid(), TG_TABLE_NAME, row_id, event_action, fields);
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_patient_registration(_request_id uuid, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE target_request public.patient_registration_requests%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão inválida.'; END IF;
 SELECT * INTO target_request FROM public.patient_registration_requests WHERE id=_request_id FOR UPDATE;
 IF NOT FOUND OR NOT public.is_account_member(target_request.account_id) THEN RAISE EXCEPTION 'Solicitação não encontrada.'; END IF;
 IF target_request.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Esta solicitação já foi revisada.'; END IF;
 IF char_length(BTRIM(COALESCE(_reason,'')))<3 THEN RAISE EXCEPTION 'Informe o motivo da recusa.'; END IF;
 UPDATE public.patient_registration_requests SET status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),rejected_at=now(),rejection_reason=BTRIM(_reason),updated_at=now() WHERE id=_request_id;
 INSERT INTO public.audit_events(account_id,actor_user_id,entity_type,entity_id,action,changed_fields) VALUES(target_request.account_id,auth.uid(),'patient_registration',_request_id,'rejected',ARRAY['status','rejection_reason']);
END;$function$

CREATE OR REPLACE FUNCTION public.reply_support_ticket(_ticket_id uuid, _message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  _message_id uuid;
  _account_id uuid;
BEGIN
  SELECT account_id INTO _account_id FROM public.support_tickets
  WHERE id = _ticket_id AND user_id = auth.uid() AND status <> 'resolved';
  IF _account_id IS NULL THEN RAISE EXCEPTION 'Ticket unavailable'; END IF;
  IF char_length(trim(_message)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Invalid message'; END IF;
  INSERT INTO public.support_messages(ticket_id, account_id, author_user_id, author_type, message)
  VALUES (_ticket_id, _account_id, auth.uid(), 'professional', trim(_message)) RETURNING id INTO _message_id;
  RETURN _message_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_subscription_contract()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE acc uuid;
BEGIN
  SELECT am.account_id INTO acc FROM public.account_members am WHERE am.user_id = auth.uid() AND am.status = 'active' ORDER BY am.created_at LIMIT 1;
  IF acc IS NULL THEN RAISE EXCEPTION 'Conta não encontrada.'; END IF;
  IF EXISTS (SELECT 1 FROM public.access_grant_events WHERE account_id = acc AND action = 'contract.requested' AND created_at > now() - interval '1 day') THEN RETURN; END IF;
  INSERT INTO public.access_grant_events(account_id, actor_user_id, action) VALUES (acc, auth.uid(), 'contract.requested');
END; $function$

CREATE OR REPLACE FUNCTION public.save_complete_patient(_payload jsonb, _patient_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target_account_id UUID;
  result_patient_id UUID;
  owner_user_id UUID;
  guardian_id UUID;
  intake JSONB;
  is_new BOOLEAN := _patient_id IS NULL;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão inválida.'; END IF;
  target_account_id := public.current_account_id();
  IF target_account_id IS NULL OR NOT public.is_account_member(target_account_id) THEN RAISE EXCEPTION 'Conta profissional não encontrada.'; END IF;
  SELECT a.owner_user_id INTO owner_user_id FROM public.accounts a WHERE a.id = target_account_id;

  IF NULLIF(BTRIM(_payload->>'full_name'), '') IS NULL OR NULLIF(_payload->>'birth_date', '') IS NULL OR NULLIF(BTRIM(_payload->>'email'), '') IS NULL OR NULLIF(BTRIM(_payload->>'cpf'), '') IS NULL OR NULLIF(BTRIM(_payload->>'postal_code'), '') IS NULL OR NULLIF(BTRIM(_payload->>'city'), '') IS NULL OR char_length(BTRIM(COALESCE(_payload->>'state', ''))) <> 2 OR NULLIF(BTRIM(_payload->>'therapy_reason'), '') IS NULL THEN
    RAISE EXCEPTION 'Revise os campos obrigatórios do cadastro.';
  END IF;

  IF _patient_id IS NULL AND EXISTS (
    SELECT 1 FROM public.patients p
    WHERE p.account_id = target_account_id
      AND (regexp_replace(COALESCE(p.cpf,''), '\D', '', 'g') = regexp_replace(_payload->>'cpf', '\D', '', 'g')
        OR (p.email IS NOT NULL AND lower(p.email) = lower(BTRIM(_payload->>'email')))
        OR (lower(p.full_name) = lower(BTRIM(_payload->>'full_name')) AND p.birth_date = (_payload->>'birth_date')::date))
  ) THEN
    RAISE EXCEPTION 'Já encontramos um cadastro semelhante. Revise antes de cadastrar.';
  END IF;

  IF _patient_id IS NULL THEN
    INSERT INTO public.patients (account_id,user_id,full_name,age_group,birth_date,gender,phone,email,address,street,city,state,status,notes,cpf,postal_code,address_number,address_complement,neighborhood,marital_status,education,occupation,registration_source)
    VALUES (target_account_id,owner_user_id,BTRIM(_payload->>'full_name'),(_payload->>'age_group')::public.age_group,(_payload->>'birth_date')::date,NULLIF(BTRIM(_payload->>'gender'),''),NULLIF(BTRIM(_payload->>'phone'),''),lower(BTRIM(_payload->>'email')),concat_ws(', ',NULLIF(BTRIM(_payload->>'street'),''),NULLIF(BTRIM(_payload->>'address_number'),''),NULLIF(BTRIM(_payload->>'address_complement'),''),NULLIF(BTRIM(_payload->>'neighborhood'),'')),NULLIF(BTRIM(_payload->>'street'),''),BTRIM(_payload->>'city'),upper(BTRIM(_payload->>'state')),COALESCE(NULLIF(_payload->>'status','')::public.patient_status,'ativo'::public.patient_status),NULLIF(BTRIM(_payload->>'notes'),''),regexp_replace(_payload->>'cpf','\D','','g'),regexp_replace(_payload->>'postal_code','\D','','g'),NULLIF(BTRIM(_payload->>'address_number'),''),NULLIF(BTRIM(_payload->>'address_complement'),''),NULLIF(BTRIM(_payload->>'neighborhood'),''),NULLIF(BTRIM(_payload->>'marital_status'),''),NULLIF(BTRIM(_payload->>'education'),''),NULLIF(BTRIM(_payload->>'occupation'),''),'manual') RETURNING id INTO result_patient_id;
  ELSE
    UPDATE public.patients p SET full_name=BTRIM(_payload->>'full_name'),age_group=(_payload->>'age_group')::public.age_group,birth_date=(_payload->>'birth_date')::date,gender=NULLIF(BTRIM(_payload->>'gender'),''),phone=NULLIF(BTRIM(_payload->>'phone'),''),email=lower(BTRIM(_payload->>'email')),address=concat_ws(', ',NULLIF(BTRIM(_payload->>'street'),''),NULLIF(BTRIM(_payload->>'address_number'),''),NULLIF(BTRIM(_payload->>'address_complement'),''),NULLIF(BTRIM(_payload->>'neighborhood'),'')),street=NULLIF(BTRIM(_payload->>'street'),''),city=BTRIM(_payload->>'city'),state=upper(BTRIM(_payload->>'state')),status=COALESCE(NULLIF(_payload->>'status','')::public.patient_status,p.status),notes=NULLIF(BTRIM(_payload->>'notes'),''),cpf=regexp_replace(_payload->>'cpf','\D','','g'),postal_code=regexp_replace(_payload->>'postal_code','\D','','g'),address_number=NULLIF(BTRIM(_payload->>'address_number'),''),address_complement=NULLIF(BTRIM(_payload->>'address_complement'),''),neighborhood=NULLIF(BTRIM(_payload->>'neighborhood'),''),marital_status=NULLIF(BTRIM(_payload->>'marital_status'),''),education=NULLIF(BTRIM(_payload->>'education'),''),occupation=NULLIF(BTRIM(_payload->>'occupation'),'')
    WHERE p.id=_patient_id AND p.account_id=target_account_id RETURNING p.id INTO result_patient_id;
    IF result_patient_id IS NULL THEN RAISE EXCEPTION 'Paciente não encontrado.'; END IF;
  END IF;

  IF (_payload->>'age_group') <> 'adulto' AND NULLIF(BTRIM(_payload->>'guardian_name'),'') IS NOT NULL THEN
    SELECT g.id INTO guardian_id FROM public.guardians g WHERE g.patient_id=result_patient_id AND g.account_id=target_account_id AND g.is_primary ORDER BY g.created_at LIMIT 1;
    IF guardian_id IS NULL THEN
      INSERT INTO public.guardians(account_id,user_id,patient_id,full_name,relationship,phone,email,is_primary) VALUES(target_account_id,owner_user_id,result_patient_id,BTRIM(_payload->>'guardian_name'),NULLIF(BTRIM(_payload->>'guardian_relationship'),''),NULLIF(BTRIM(_payload->>'guardian_phone'),''),NULLIF(lower(BTRIM(_payload->>'guardian_email')),''),true);
    ELSE
      UPDATE public.guardians SET full_name=BTRIM(_payload->>'guardian_name'),relationship=NULLIF(BTRIM(_payload->>'guardian_relationship'),''),phone=NULLIF(BTRIM(_payload->>'guardian_phone'),''),email=NULLIF(lower(BTRIM(_payload->>'guardian_email')),'') WHERE id=guardian_id;
    END IF;
  END IF;

  intake := jsonb_build_object('motivo_busca',_payload->>'therapy_reason','terapia_anterior',_payload->>'previous_therapy','detalhes_terapia_anterior',NULLIF(BTRIM(_payload->>'previous_therapy_details'),''),'diagnostico_medico',_payload->>'medical_diagnosis','detalhes_diagnostico',NULLIF(BTRIM(_payload->>'medical_diagnosis_details'),''),'uso_medicamento',_payload->>'medication_use','detalhes_medicamento',NULLIF(BTRIM(_payload->>'medication_details'),''),'historico_familiar_saude_mental',_payload->>'family_mental_health','detalhes_historico_familiar',NULLIF(BTRIM(_payload->>'family_mental_health_details'),''),'contato_emergencia',jsonb_build_object('nome',NULLIF(BTRIM(_payload->>'emergency_name'),''),'vinculo',NULLIF(BTRIM(_payload->>'emergency_relationship'),''),'telefone',NULLIF(BTRIM(_payload->>'emergency_phone'),''),'observacao',NULLIF(BTRIM(_payload->>'emergency_notes'),'')),'preferencia_pagamento',NULLIF(_payload->>'payment_preference',''),'origem',NULLIF(_payload->>'referral_source',''),'origem_outro',NULLIF(BTRIM(_payload->>'referral_source_other'),''));
  IF is_new THEN
    INSERT INTO public.anamneses(account_id,user_id,patient_id,title,template_key,content,is_completed) VALUES(target_account_id,owner_user_id,result_patient_id,'Informações iniciais do cadastro','patient_registration',intake,true);
  ELSE
    UPDATE public.anamneses SET content=intake,updated_at=now() WHERE id=(SELECT a.id FROM public.anamneses a WHERE a.patient_id=result_patient_id AND a.account_id=target_account_id AND a.template_key='patient_registration' ORDER BY a.created_at LIMIT 1);
    IF NOT FOUND THEN INSERT INTO public.anamneses(account_id,user_id,patient_id,title,template_key,content,is_completed) VALUES(target_account_id,owner_user_id,result_patient_id,'Informações iniciais do cadastro','patient_registration',intake,true); END IF;
  END IF;
  RETURN result_patient_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_patient_registration_review(_request_id uuid, _payload jsonb)
