 IF NOT FOUND OR NOT public.is_account_member(target_request.account_id) THEN RAISE EXCEPTION 'Solicitação não encontrada.'; END IF;
 IF target_request.status<>'awaiting_approval' THEN RAISE EXCEPTION 'Esta solicitação já foi revisada.'; END IF;
 IF NULLIF(BTRIM(_payload->>'full_name'),'') IS NULL OR NULLIF(_payload->>'birth_date','') IS NULL OR NULLIF(BTRIM(_payload->>'email'),'') IS NULL OR NULLIF(BTRIM(_payload->>'cpf'),'') IS NULL OR NULLIF(BTRIM(_payload->>'postal_code'),'') IS NULL OR NULLIF(BTRIM(_payload->>'city'),'') IS NULL OR char_length(BTRIM(COALESCE(_payload->>'state','')))<>2 OR NULLIF(BTRIM(_payload->>'therapy_reason'),'') IS NULL THEN RAISE EXCEPTION 'Revise os campos obrigatórios do cadastro.'; END IF;
 UPDATE public.patient_registration_requests SET full_name=BTRIM(_payload->>'full_name'),email=lower(BTRIM(_payload->>'email')),birth_date=(_payload->>'birth_date')::date,cpf=regexp_replace(_payload->>'cpf','\D','','g'),age_group=(_payload->>'age_group')::public.age_group,gender=NULLIF(BTRIM(_payload->>'gender'),''),marital_status=NULLIF(BTRIM(_payload->>'marital_status'),''),education=NULLIF(BTRIM(_payload->>'education'),''),occupation=NULLIF(BTRIM(_payload->>'occupation'),''),phone=NULLIF(BTRIM(_payload->>'phone'),''),postal_code=regexp_replace(_payload->>'postal_code','\D','','g'),street=NULLIF(BTRIM(_payload->>'street'),''),address_number=NULLIF(BTRIM(_payload->>'address_number'),''),address_complement=NULLIF(BTRIM(_payload->>'address_complement'),''),neighborhood=NULLIF(BTRIM(_payload->>'neighborhood'),''),city=BTRIM(_payload->>'city'),state=upper(BTRIM(_payload->>'state')),guardian_name=NULLIF(BTRIM(_payload->>'guardian_name'),''),guardian_relationship=NULLIF(BTRIM(_payload->>'guardian_relationship'),''),guardian_phone=NULLIF(BTRIM(_payload->>'guardian_phone'),''),guardian_email=NULLIF(lower(BTRIM(_payload->>'guardian_email')),''),emergency_name=NULLIF(BTRIM(_payload->>'emergency_name'),''),emergency_relationship=NULLIF(BTRIM(_payload->>'emergency_relationship'),''),emergency_phone=NULLIF(BTRIM(_payload->>'emergency_phone'),''),emergency_notes=NULLIF(BTRIM(_payload->>'emergency_notes'),''),therapy_reason=BTRIM(_payload->>'therapy_reason'),previous_therapy=_payload->>'previous_therapy',previous_therapy_details=NULLIF(BTRIM(_payload->>'previous_therapy_details'),''),medical_diagnosis=_payload->>'medical_diagnosis',medical_diagnosis_details=NULLIF(BTRIM(_payload->>'medical_diagnosis_details'),''),medication_use=_payload->>'medication_use',medication_details=NULLIF(BTRIM(_payload->>'medication_details'),''),family_mental_health=_payload->>'family_mental_health',family_mental_health_details=NULLIF(BTRIM(_payload->>'family_mental_health_details'),''),payment_preference=NULLIF(_payload->>'payment_preference',''),referral_source=NULLIF(_payload->>'referral_source',''),referral_source_other=NULLIF(BTRIM(_payload->>'referral_source_other'),''),reviewed_data=_payload,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=_request_id;
 INSERT INTO public.audit_events(account_id,actor_user_id,entity_type,entity_id,action,changed_fields) VALUES(target_request.account_id,auth.uid(),'patient_registration',_request_id,'review_updated',ARRAY['reviewed_data']);
 RETURN _request_id;
END;$function$

CREATE OR REPLACE FUNCTION public.save_service_price(_price_id uuid, _appointment_type_id uuid, _price_cents integer, _duration_minutes integer, _modality text, _billing_type text, _package_quantity integer, _is_active boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  target_account_id UUID;
  existing_price public.service_prices%ROWTYPE;
  result_id UUID;
  effective_quantity INTEGER;
BEGIN
  target_account_id := public.current_account_id();
  effective_quantity := CASE WHEN _billing_type = 'avulso' THEN NULL ELSE _package_quantity END;
  IF target_account_id IS NULL OR NOT public.is_account_member(target_account_id) THEN RAISE EXCEPTION 'Conta profissional não encontrada.'; END IF;
  IF _price_cents < 0 OR _duration_minutes < 5 OR _duration_minutes > 720 THEN RAISE EXCEPTION 'Revise o valor e a duração.'; END IF;
  IF _modality NOT IN ('presencial','online','hibrido','todas') OR _billing_type NOT IN ('avulso','pacote') THEN RAISE EXCEPTION 'Configuração de valor inválida.'; END IF;
  IF _billing_type = 'pacote' AND COALESCE(effective_quantity, 0) < 1 THEN RAISE EXCEPTION 'Revise a quantidade do pacote.'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE id = _appointment_type_id AND account_id = target_account_id) THEN RAISE EXCEPTION 'Serviço não encontrado.'; END IF;

  IF _price_id IS NULL THEN
    INSERT INTO public.service_prices (account_id, appointment_type_id, price_cents, duration_minutes, modality, billing_type, package_quantity, is_active)
    VALUES (target_account_id, _appointment_type_id, _price_cents, _duration_minutes, _modality, _billing_type, effective_quantity, _is_active)
    RETURNING id INTO result_id;
    RETURN result_id;
  END IF;

  SELECT * INTO existing_price FROM public.service_prices WHERE id = _price_id AND account_id = target_account_id FOR UPDATE;
  IF existing_price.id IS NULL THEN RAISE EXCEPTION 'Valor não encontrado.'; END IF;

  IF existing_price.appointment_type_id = _appointment_type_id
     AND existing_price.price_cents = _price_cents
     AND existing_price.duration_minutes = _duration_minutes
     AND existing_price.modality = _modality
     AND existing_price.billing_type = _billing_type
     AND existing_price.package_quantity IS NOT DISTINCT FROM effective_quantity THEN
    UPDATE public.service_prices SET is_active = _is_active WHERE id = existing_price.id;
    RETURN existing_price.id;
  END IF;

  UPDATE public.service_prices SET is_active = false WHERE id = existing_price.id;
  INSERT INTO public.service_prices (account_id, appointment_type_id, price_cents, duration_minutes, modality, billing_type, package_quantity, is_active, parent_price_id)
  VALUES (target_account_id, _appointment_type_id, _price_cents, _duration_minutes, _modality, _billing_type, effective_quantity, _is_active, existing_price.id)
  RETURNING id INTO result_id;
  RETURN result_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.schedule_care_package(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid:=public.current_account_id(); p public.care_packages%ROWTYPE; price public.service_prices%ROWTYPE; pid uuid; patient uuid; key uuid; quantity integer; total integer; discount integer; unit integer; mode text; mod public.appointment_modality; dur integer; slot jsonb; n integer; used integer; start_at timestamptz; end_at timestamptz;
BEGIN
 IF NOT coalesce(public.can_manage_professional_finance(aid),false) THEN RAISE EXCEPTION 'Sem permissão para contratar/agendar pacote.'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(aid::text,0));
 key:=(_payload->>'request_key')::uuid; IF key IS NULL THEN RAISE EXCEPTION 'Identificador da operação obrigatório.'; END IF;
 SELECT package_id INTO pid FROM public.appointments WHERE account_id=aid AND package_scheduling_key=key LIMIT 1; IF pid IS NOT NULL THEN RETURN pid; END IF;
 IF jsonb_typeof(_payload->'slots') IS DISTINCT FROM 'array' OR jsonb_array_length(_payload->'slots')<1 THEN RAISE EXCEPTION 'Informe as datas das sessões.'; END IF;
 n:=jsonb_array_length(_payload->'slots');
 IF nullif(_payload->>'package_id','') IS NOT NULL THEN
 SELECT * INTO p FROM public.care_packages WHERE id=(_payload->>'package_id')::uuid AND account_id=aid FOR UPDATE; IF p.id IS NULL OR p.lifecycle_status<>'ativo' THEN RAISE EXCEPTION 'Pacote ativo não encontrado.'; END IF;
 pid:=p.id; patient:=p.patient_id; quantity:=p.quantity; dur:=coalesce(p.contracted_duration_minutes,(_payload->>'duration_minutes')::integer,50); mod:=coalesce(p.scheduled_modality,(_payload->>'modality')::public.appointment_modality);
 SELECT count(*) INTO used FROM public.appointments WHERE package_id=p.id; IF used+n>quantity THEN RAISE EXCEPTION 'A quantidade de sessões vinculadas ultrapassa o contrato. Reagende sessões existentes.'; END IF;
 ELSE
 SELECT id INTO pid FROM public.care_packages WHERE account_id=aid AND scheduling_key=key; IF pid IS NOT NULL THEN RETURN pid; END IF;
 SELECT * INTO price FROM public.service_prices WHERE id=(_payload->>'service_price_id')::uuid AND account_id=aid AND is_active; IF price.id IS NULL THEN RAISE EXCEPTION 'Selecione um preço ativo.'; END IF;
 patient:=(_payload->>'patient_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.patients WHERE id=patient AND account_id=aid) THEN RAISE EXCEPTION 'Paciente inválido.'; END IF;
 quantity:=(_payload->>'quantity')::integer; IF quantity IS NULL OR quantity<1 OR quantity<>n THEN RAISE EXCEPTION 'Revise a quantidade e as datas.'; END IF;
 dur:=price.duration_minutes; mod:=(_payload->>'modality')::public.appointment_modality; IF mod IS NULL OR mod NOT IN ('presencial','online') OR NOT (price.modality IN ('todas','hibrido') OR price.modality=mod::text) THEN RAISE EXCEPTION 'Modalidade incompatível com o preço.'; END IF;
 unit:=CASE WHEN price.billing_type='avulso' THEN price.price_cents ELSE round(price.price_cents::numeric/price.package_quantity)::integer END; discount:=coalesce((_payload->>'discount_cents')::integer,0);
 total:=CASE WHEN price.billing_type='pacote' AND quantity=price.package_quantity THEN price.price_cents ELSE unit*quantity END-discount;
 mode:=_payload->>'finance_mode'; IF total IS NULL OR total<0 OR discount<0 OR mode IS NULL OR mode NOT IN ('prepaid','per_session') THEN RAISE EXCEPTION 'Revise desconto e modelo financeiro.'; END IF;
 INSERT INTO public.care_packages(account_id,user_id,patient_id,appointment_type_id,service_price_id,quantity,total_value_cents,start_date,periodicity,renewal_alert_threshold,finance_mode,contracted_unit_cents,discount_cents,scheduled_modality,contracted_duration_minutes,scheduling_key) VALUES(aid,auth.uid(),patient,price.appointment_type_id,price.id,quantity,total,(_payload->'slots'->0->>'date')::date,CASE WHEN _payload->>'frequency'='weekly' THEN 'semanal'::public.care_package_periodicity WHEN _payload->>'frequency'='fortnightly' THEN 'quinzenal'::public.care_package_periodicity ELSE 'personalizada'::public.care_package_periodicity END,least(2,quantity),mode,unit,discount,mod,dur,key) RETURNING * INTO p; pid:=p.id;
 END IF;
 IF dur<5 OR dur>720 OR mod IS NULL THEN RAISE EXCEPTION 'Duração/modalidade inválida.'; END IF;
 FOR slot IN SELECT value FROM jsonb_array_elements(_payload->'slots') LOOP
 IF nullif(slot->>'date','') IS NULL OR nullif(slot->>'time','') IS NULL THEN RAISE EXCEPTION 'Data e horário obrigatórios em todas as sessões.'; END IF;
 start_at:=((slot->>'date')||' '||(slot->>'time'))::timestamp AT TIME ZONE 'America/Sao_Paulo'; end_at:=start_at+make_interval(mins=>dur);
 INSERT INTO public.appointments(account_id,user_id,patient_id,appointment_type_id,package_id,package_scheduling_key,starts_at,ends_at,modality,location_id,room_id,status,service_name_snapshot,duration_minutes_snapshot) VALUES(aid,auth.uid(),patient,p.appointment_type_id,pid,key,start_at,end_at,mod,nullif(_payload->>'location_id','')::uuid,nullif(_payload->>'room_id','')::uuid,'agendado',p.service_name_snapshot,dur);
 END LOOP; RETURN pid;
END $function$

CREATE OR REPLACE FUNCTION public.schedule_contract_package(_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE aid uuid := public.current_account_id(); key uuid; pid uuid; patient uuid; qty integer; total integer; dur integer; mod public.appointment_modality; mode text; tid uuid; slot jsonb; idx integer := 0; start_at timestamptz; end_at timestamptz; loc uuid;
BEGIN
  IF NOT coalesce(public.can_manage_professional_finance(aid),false) THEN RAISE EXCEPTION 'Sem permissão para contratar pacote.'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(aid::text,0));
  key := (_payload->>'request_key')::uuid; IF key IS NULL THEN RAISE EXCEPTION 'Identificador da operação obrigatório.'; END IF;
  SELECT id INTO pid FROM public.care_packages WHERE account_id=aid AND scheduling_key=key; IF pid IS NOT NULL THEN RETURN pid; END IF;
  IF jsonb_typeof(_payload->'slots') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Informe as datas das sessões.'; END IF;
  qty := jsonb_array_length(_payload->'slots');
  IF qty < 1 OR qty <> (_payload->>'quantity')::integer THEN RAISE EXCEPTION 'A quantidade de datas não corresponde ao pacote.'; END IF;
  patient := (_payload->>'patient_id')::uuid;
  IF NOT EXISTS (SELECT 1 FROM public.patients WHERE id=patient AND account_id=aid) THEN RAISE EXCEPTION 'Paciente inválido.'; END IF;
  total := (_payload->>'total_cents')::integer; IF total IS NULL OR total < 0 THEN RAISE EXCEPTION 'Informe o valor total do pacote.'; END IF;
  dur := (_payload->>'duration_minutes')::integer; IF dur IS NULL OR dur < 5 OR dur > 720 THEN RAISE EXCEPTION 'Duração inválida.'; END IF;
  mod := (_payload->>'modality')::public.appointment_modality;
  mode := coalesce(_payload->>'finance_mode','prepaid'); IF mode NOT IN ('prepaid','per_session') THEN RAISE EXCEPTION 'Modelo financeiro inválido.'; END IF;
  tid := nullif(_payload->>'appointment_type_id','')::uuid;
  INSERT INTO public.care_packages(account_id,user_id,patient_id,appointment_type_id,quantity,total_value_cents,start_date,periodicity,renewal_alert_threshold,finance_mode,contracted_unit_cents,discount_cents,scheduled_modality,contracted_duration_minutes,scheduling_key)
  VALUES (aid,auth.uid(),patient,tid,qty,total,(_payload->'slots'->0->>'date')::date,CASE WHEN _payload->>'frequency'='weekly' THEN 'semanal'::public.care_package_periodicity ELSE 'personalizada'::public.care_package_periodicity END,least(2,qty),mode,round(total::numeric/qty)::integer,0,mod,dur,key)
  RETURNING id INTO pid;
  FOR slot IN SELECT value FROM jsonb_array_elements(_payload->'slots') LOOP
    idx := idx + 1;
    IF nullif(slot->>'date','') IS NULL OR nullif(slot->>'time','') IS NULL THEN RAISE EXCEPTION 'Sessão % de %: informe data e horário.', idx, qty; END IF;
    start_at := ((slot->>'date')||' '||(slot->>'time'))::timestamp AT TIME ZONE 'America/Sao_Paulo';
    end_at := start_at + make_interval(mins=>dur);
    loc := nullif(slot->>'location_id','')::uuid;
    BEGIN
      INSERT INTO public.appointments(account_id,user_id,patient_id,appointment_type_id,package_id,package_scheduling_key,starts_at,ends_at,modality,location_id,status,duration_minutes_snapshot)
      VALUES (aid,auth.uid(),patient,tid,pid,key,start_at,end_at,mod,loc,'agendado',dur);
    EXCEPTION WHEN exclusion_violation THEN
      RAISE EXCEPTION 'Sessão % de %: este horário já está ocupado.', idx, qty;
    WHEN OTHERS THEN
      RAISE EXCEPTION 'Sessão % de %: %', idx, qty, SQLERRM;
    END;
  END LOOP;
  RETURN pid;
END $function$

CREATE OR REPLACE FUNCTION public.set_profile_specialties(_profile_id uuid, _specialty_ids uuid[], _primary_specialty_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  target_account_id UUID;
BEGIN
  SELECT account_id INTO target_account_id
  FROM public.profiles
  WHERE id = _profile_id;

  IF target_account_id IS NULL OR NOT public.is_account_member(target_account_id) THEN
    RAISE EXCEPTION 'Perfil profissional não encontrado.';
  END IF;
  IF _primary_specialty_id IS NULL OR NOT (_primary_specialty_id = ANY(_specialty_ids)) THEN
    RAISE EXCEPTION 'Selecione uma especialidade principal.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(_specialty_ids) AS selected_id
    WHERE NOT EXISTS (
      SELECT 1 FROM public.specialties
      WHERE id = selected_id AND account_id = target_account_id AND is_active
    )
  ) THEN
    RAISE EXCEPTION 'Especialidade inválida para esta conta.';
  END IF;

  DELETE FROM public.profile_specialties
  WHERE profile_id = _profile_id;

  INSERT INTO public.profile_specialties (account_id, profile_id, specialty_id, is_primary)
  SELECT target_account_id, _profile_id, selected_id, selected_id = _primary_specialty_id
  FROM unnest(_specialty_ids) AS selected_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.snapshot_appointment_service_price()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  selected_price public.service_prices%ROWTYPE;
  selected_service public.appointment_types%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = 'realizado' AND (
    NEW.appointment_type_id IS DISTINCT FROM OLD.appointment_type_id OR
    NEW.service_price_id IS DISTINCT FROM OLD.service_price_id OR
    NEW.service_name_snapshot IS DISTINCT FROM OLD.service_name_snapshot OR
    NEW.price_cents_snapshot IS DISTINCT FROM OLD.price_cents_snapshot OR
    NEW.duration_minutes_snapshot IS DISTINCT FROM OLD.duration_minutes_snapshot
  ) THEN
    RAISE EXCEPTION 'O serviço e o valor de um atendimento realizado não podem ser alterados.';
  END IF;

  IF NEW.service_price_id IS NOT NULL AND (TG_OP = 'INSERT' OR NEW.service_price_id IS DISTINCT FROM OLD.service_price_id) THEN
    SELECT * INTO selected_price FROM public.service_prices WHERE id = NEW.service_price_id AND account_id = NEW.account_id;
    IF selected_price.id IS NULL OR selected_price.billing_type <> 'avulso' THEN RAISE EXCEPTION 'Valor avulso inválido para esta conta.'; END IF;
    NEW.appointment_type_id := selected_price.appointment_type_id;
    NEW.price_cents_snapshot := selected_price.price_cents;
    NEW.duration_minutes_snapshot := selected_price.duration_minutes;
  END IF;

  IF NEW.appointment_type_id IS NOT NULL AND (NEW.service_name_snapshot IS NULL OR TG_OP = 'INSERT') THEN
    SELECT * INTO selected_service FROM public.appointment_types WHERE id = NEW.appointment_type_id AND account_id = NEW.account_id;
    IF selected_service.id IS NULL THEN RAISE EXCEPTION 'Serviço inválido para esta conta.'; END IF;
    NEW.service_name_snapshot := selected_service.name;
    NEW.duration_minutes_snapshot := COALESCE(NEW.duration_minutes_snapshot, selected_service.default_duration_minutes);
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.snapshot_care_package_price()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE price public.service_prices%ROWTYPE; service public.appointment_types%ROWTYPE;
BEGIN
 IF TG_OP='UPDATE' AND (OLD.lifecycle_status IN ('encerrado','cancelado') OR EXISTS(SELECT 1 FROM public.professional_receivables WHERE package_id=OLD.id)) AND (NEW.appointment_type_id IS DISTINCT FROM OLD.appointment_type_id OR NEW.service_price_id IS DISTINCT FROM OLD.service_price_id OR NEW.service_name_snapshot IS DISTINCT FROM OLD.service_name_snapshot OR NEW.total_value_cents IS DISTINCT FROM OLD.total_value_cents OR NEW.total_value IS DISTINCT FROM OLD.total_value OR NEW.quantity IS DISTINCT FROM OLD.quantity OR NEW.finance_mode IS DISTINCT FROM OLD.finance_mode OR NEW.discount_cents IS DISTINCT FROM OLD.discount_cents OR NEW.contracted_unit_cents IS DISTINCT FROM OLD.contracted_unit_cents) THEN RAISE EXCEPTION 'Contrato com histórico financeiro ou encerrado não pode ser reescrito. Crie uma renovação.'; END IF;
 IF NEW.service_price_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.service_price_id IS DISTINCT FROM OLD.service_price_id) THEN
 SELECT * INTO price FROM public.service_prices WHERE id=NEW.service_price_id AND account_id=NEW.account_id;
 IF price.id IS NULL OR NOT price.is_active THEN RAISE EXCEPTION 'Preço não disponível para esta conta.'; END IF;
 IF price.billing_type='avulso' AND NEW.scheduling_key IS NULL THEN RAISE EXCEPTION 'Selecione uma oferta de pacote.'; END IF;
 NEW.appointment_type_id:=price.appointment_type_id;
 IF NEW.scheduling_key IS NULL THEN NEW.quantity:=price.package_quantity; NEW.total_value_cents:=price.price_cents; END IF;
 END IF;
 IF NEW.total_value_cents IS NULL AND NEW.total_value IS NOT NULL THEN NEW.total_value_cents:=round(NEW.total_value*100)::integer; END IF;
 IF NEW.total_value_cents IS NOT NULL THEN NEW.total_value:=NEW.total_value_cents::numeric/100; NEW.value_per_session_cents:=round(NEW.total_value_cents::numeric/NEW.quantity)::integer; NEW.value_per_session:=NEW.value_per_session_cents::numeric/100; END IF;
 IF NEW.appointment_type_id IS NOT NULL AND (NEW.service_name_snapshot IS NULL OR TG_OP='INSERT') THEN SELECT * INTO service FROM public.appointment_types WHERE id=NEW.appointment_type_id AND account_id=NEW.account_id; IF service.id IS NULL THEN RAISE EXCEPTION 'Serviço inválido.'; END IF; NEW.service_name_snapshot:=service.name; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.start_standard_trial_on_onboarding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE new_grant uuid;
BEGIN
  IF NEW.onboarding_completed AND NOT coalesce(OLD.onboarding_completed, false) AND NEW.account_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.access_grants WHERE account_id = NEW.account_id) THEN
    INSERT INTO public.access_grants(account_id, kind, starts_at, ends_at, reason)
    VALUES (NEW.account_id, 'standard_trial', now(), now() + interval '7 days', 'Teste gratuito padrão')
    ON CONFLICT DO NOTHING RETURNING id INTO new_grant;
    IF new_grant IS NOT NULL THEN
      INSERT INTO public.access_grant_events(account_id, grant_id, actor_user_id, action, new_values)
      VALUES (NEW.account_id, new_grant, NEW.id, 'trial.started', jsonb_build_object('days', 7));
    END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.submit_patient_registration(_token_hash text, _bucket_key text, _payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE target_link public.patient_registration_links%ROWTYPE; request_id UUID; limiter public.patient_registration_rate_limits%ROWTYPE; stored_payload JSONB;
BEGIN
 IF char_length(_token_hash)<>64 OR char_length(_bucket_key)<>64 THEN RAISE EXCEPTION 'Este link não está mais disponível.'; END IF;
 SELECT * INTO target_link FROM public.patient_registration_links WHERE token_hash=_token_hash FOR UPDATE;
 IF NOT FOUND OR target_link.revoked_at IS NOT NULL OR target_link.expires_at<=now() OR target_link.uses_count>=target_link.max_uses THEN RAISE EXCEPTION 'Este link não está mais disponível.'; END IF;
 SELECT * INTO limiter FROM public.patient_registration_rate_limits WHERE bucket_key=_bucket_key FOR UPDATE;
 IF FOUND AND limiter.window_started_at>now()-interval '1 hour' AND limiter.attempts>=10 THEN RAISE EXCEPTION 'Muitas tentativas. Aguarde antes de tentar novamente.'; END IF;
 IF NOT FOUND OR limiter.window_started_at<=now()-interval '1 hour' THEN INSERT INTO public.patient_registration_rate_limits(bucket_key,window_started_at,attempts) VALUES(_bucket_key,now(),1) ON CONFLICT(bucket_key) DO UPDATE SET window_started_at=now(),attempts=1,updated_at=now(); ELSE UPDATE public.patient_registration_rate_limits SET attempts=attempts+1,updated_at=now() WHERE bucket_key=_bucket_key; END IF;
 stored_payload:=_payload-'privacy_consent';
 INSERT INTO public.patient_registration_requests(account_id,link_id,full_name,email,birth_date,cpf,age_group,gender,marital_status,education,occupation,phone,postal_code,street,address_number,address_complement,neighborhood,city,state,guardian_name,guardian_relationship,guardian_phone,guardian_email,emergency_name,emergency_relationship,emergency_phone,emergency_notes,therapy_reason,previous_therapy,previous_therapy_details,medical_diagnosis,medical_diagnosis_details,medication_use,medication_details,family_mental_health,family_mental_health_details,payment_preference,referral_source,referral_source_other,privacy_consent_at,original_data,reviewed_data)
