CREATE OR REPLACE FUNCTION public.validate_appointment_package()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  selected_package public.care_packages%ROWTYPE;
  used_sessions INTEGER;
BEGIN
  IF NEW.package_id IS NULL THEN
    IF TG_OP = 'UPDATE' AND OLD.status = 'realizado' AND OLD.package_id IS NOT NULL THEN
      RAISE EXCEPTION 'Uma sessão realizada não pode ser removida do pacote.';
    END IF;
    NEW.package_session_value := NULL;
    RETURN NEW;
  END IF;

  SELECT * INTO selected_package
  FROM public.care_packages p
  WHERE p.id = NEW.package_id
    AND p.account_id = NEW.account_id
    AND p.patient_id = NEW.patient_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'O pacote informado não pertence a este paciente e conta.';
  END IF;

  IF selected_package.lifecycle_status <> 'ativo'
     AND (TG_OP = 'INSERT' OR OLD.package_id IS DISTINCT FROM NEW.package_id) THEN
    RAISE EXCEPTION 'O pacote informado não está ativo para este paciente.';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'realizado' THEN
    IF OLD.package_id IS DISTINCT FROM NEW.package_id THEN
      RAISE EXCEPTION 'Uma sessão realizada não pode ser transferida para outro pacote.';
    END IF;
    NEW.package_session_value := OLD.package_session_value;
  ELSIF NEW.status = 'realizado' THEN
    SELECT count(*)::INTEGER INTO used_sessions
    FROM public.appointments a
    WHERE a.package_id = NEW.package_id
      AND a.status = 'realizado'
      AND (TG_OP = 'INSERT' OR a.id <> NEW.id);

    IF used_sessions >= selected_package.quantity THEN
      RAISE EXCEPTION 'Este pacote já utilizou todas as sessões contratadas.';
    END IF;

    NEW.package_session_value := selected_package.value_per_session;
  ELSE
    NEW.package_session_value := NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_basic_registration_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  target_account UUID;
BEGIN
  IF TG_TABLE_NAME = 'profile_specialties' THEN
    SELECT account_id INTO target_account FROM public.profiles WHERE id = NEW.profile_id;
    IF target_account IS DISTINCT FROM NEW.account_id OR NOT EXISTS (SELECT 1 FROM public.specialties WHERE id = NEW.specialty_id AND account_id = NEW.account_id) THEN
      RAISE EXCEPTION 'Especialidade não pertence a esta conta.';
    END IF;
  ELSIF TG_TABLE_NAME = 'service_prices' THEN
    IF NOT EXISTS (SELECT 1 FROM public.appointment_types WHERE id = NEW.appointment_type_id AND account_id = NEW.account_id) THEN
      RAISE EXCEPTION 'Serviço não pertence a esta conta.';
    END IF;
    IF NEW.parent_price_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.service_prices WHERE id = NEW.parent_price_id AND account_id = NEW.account_id) THEN
      RAISE EXCEPTION 'Valor anterior não pertence a esta conta.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_care_package()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  used_sessions INTEGER;
BEGIN
  IF NEW.account_id IS NULL OR NOT public.is_account_member(NEW.account_id) THEN
    RAISE EXCEPTION 'A conta informada não está disponível para este usuário.';
  END IF;
  IF NEW.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'O profissional informado não corresponde à sessão atual.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.patients p WHERE p.id = NEW.patient_id AND p.account_id = NEW.account_id
  ) THEN
    RAISE EXCEPTION 'O paciente informado não pertence a esta conta.';
  END IF;
  IF NEW.appointment_type_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.appointment_types t WHERE t.id = NEW.appointment_type_id AND t.account_id = NEW.account_id
  ) THEN
    RAISE EXCEPTION 'O serviço informado não pertence a esta conta.';
  END IF;
  IF NEW.parent_package_id IS NOT NULL THEN
    IF NEW.parent_package_id = NEW.id OR NOT EXISTS (
      SELECT 1 FROM public.care_packages p
      WHERE p.id = NEW.parent_package_id AND p.account_id = NEW.account_id AND p.patient_id = NEW.patient_id
    ) THEN
      RAISE EXCEPTION 'O pacote anterior não pertence ao mesmo paciente desta conta.';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.quantity < OLD.quantity THEN
    SELECT count(*)::INTEGER INTO used_sessions
    FROM public.appointments a
    WHERE a.package_id = NEW.id AND a.status = 'realizado';
    IF NEW.quantity < used_sessions THEN
      RAISE EXCEPTION 'Não é possível reduzir o pacote para uma quantidade inferior ao número de sessões já utilizadas.';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_owned_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.account_id IS NULL OR NOT public.is_account_member(NEW.account_id) THEN
    RAISE EXCEPTION 'A conta informada não está disponível para este usuário.';
  END IF;
  IF TG_TABLE_NAME = 'guardians' THEN
    IF NOT EXISTS (SELECT 1 FROM public.patients p WHERE p.id=NEW.patient_id AND p.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O paciente informado não pertence a esta conta.'; END IF;
  ELSIF TG_TABLE_NAME = 'appointments' THEN
    IF NEW.patient_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.patients p WHERE p.id=NEW.patient_id AND p.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O paciente informado não pertence a esta conta.'; END IF;
    IF NEW.location_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.locations l WHERE l.id=NEW.location_id AND l.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O local informado não pertence a esta conta.'; END IF;
    IF NEW.room_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.rooms r WHERE r.id=NEW.room_id AND r.account_id=NEW.account_id AND (NEW.location_id IS NULL OR r.location_id=NEW.location_id)) THEN RAISE EXCEPTION 'A sala informada não pertence ao local desta conta.'; END IF;
    IF NEW.appointment_type_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.appointment_types t WHERE t.id=NEW.appointment_type_id AND t.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O tipo de atendimento não pertence a esta conta.'; END IF;
  ELSIF TG_TABLE_NAME = 'anamneses' THEN
    IF NOT EXISTS (SELECT 1 FROM public.patients p WHERE p.id=NEW.patient_id AND p.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O paciente informado não pertence a esta conta.'; END IF;
    IF NEW.appointment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.appointments a WHERE a.id=NEW.appointment_id AND a.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O atendimento informado não pertence a esta conta.'; END IF;
  ELSIF TG_TABLE_NAME = 'evolutions' THEN
    IF NOT EXISTS (SELECT 1 FROM public.patients p WHERE p.id=NEW.patient_id AND p.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O paciente informado não pertence a esta conta.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.appointments a WHERE a.id=NEW.appointment_id AND a.account_id=NEW.account_id AND a.patient_id=NEW.patient_id) THEN RAISE EXCEPTION 'O atendimento informado não pertence ao paciente desta conta.'; END IF;
  ELSIF TG_TABLE_NAME = 'documents' THEN
    IF NEW.patient_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.patients p WHERE p.id=NEW.patient_id AND p.account_id=NEW.account_id) THEN RAISE EXCEPTION 'O paciente informado não pertence a esta conta.'; END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_schedule_references()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.account_id IS NULL OR NOT public.is_account_member(NEW.account_id) THEN
    RAISE EXCEPTION 'A conta informada não está disponível para este usuário.';
  END IF;
  IF NEW.location_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.locations l WHERE l.id = NEW.location_id AND l.account_id = NEW.account_id
  ) THEN RAISE EXCEPTION 'O local informado não pertence a esta conta.'; END IF;
  IF NEW.room_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.rooms r WHERE r.id = NEW.room_id AND r.account_id = NEW.account_id
      AND (NEW.location_id IS NULL OR r.location_id = NEW.location_id)
  ) THEN RAISE EXCEPTION 'A sala informada não pertence ao local desta conta.'; END IF;
  RETURN NEW;
END; $function$
